comms.text:
@1 וְאִלֵּין תּוּלְדַת יִצְחָק בַּר אַבְרָהָם אַבְרָהָם אוֹלִיד יָת יִצְחָק:
@2 וַהֲוָה יִצְחָק בַּר אַרְבְּעִין שְׁנִין כַּד נְסֵיב יָת רִבְקָה בַּת בְּתוּאֵל אֲרַמָּאָה מִפַּדַּן אֲרָם אֲחָתֵהּ דְלָבָן אֲרַמָּאָה לֵהּ לְאִנְתּוּ:
@3 וְצַלִּי יִצְחָק קֳדָם יְיָ לָקֳבֵל אִתְּתֵהּ אֲרֵי עֲקָרָה הִיא וְקַבֵּל צְלוֹתֵהּ יְיָ וְעַדִּיאַת רִבְקָה אִתְּתֵהּ:
@4 וְדַחֲקִין בְּנַיָּא בִּמְעָהָא וַאֲמֶרֶת אִם כֵּן לְמָה דְּנַן אֲנָא וַאֲזָלַת לְמִתְבַּע אוּלְפַן מִן קֳדָם יְיָ:
@5 וַאֲמַר יְיָ לַהּ תְּרֵין עַמְמִין בִּמְעַיְכִי וְתַרְתֵּין מַלְכְּוָן מִמֵעַיְכִי יִתְפָּרְשָׁן וּמַלְכוּ מִמַלְכוּ יִתְקַף וְרַבָּא יִשְׁתַּעֲבֵּיד לִזְעֵירָא:
@6 וּשְׁלִימוּ יוֹמָהָא לְמֵילָד וְהָא תְיוּמִין בִּמְעָהָא:
@7 וּנְפַק קַדְמָאָה סִמוֹק כֻּלֵּהּ כִּגְלִים (נ''י כִּכְלָן) דִּשְׂעָר וּקְרוֹ שְׁמֵהּ עֵשָׂו:
@8 וּבָתַר כֵּן נְפַק אֲחוּהִי וִידֵהּ אֲחִידָא בְּעִקְבָא דְעֵשָׂו וּקְרָא שְׁמֵהּ יַעֲקֹב וְיִצְחָק בַּר שִׁתִּין שְׁנִין כַּד יְלִידַת יָתְהוֹן:
@9 וּרְבִיוּ עוּלֵמַיָּא וַהֲוָה עֵשָׂו גְבַר נַחְשִׁירְכָן גְבַר נָפֵק לְחַקְלָא וְיַעֲקֹב גְבַר שְׁלִים מְשַׁמֵשׁ בֵּית אוּלְפָנָא:
@10 וּרְחֵם יִצְחָק יָת עֵשָׂו אֲרֵי מִצֵידֵהּ הֲוָה אָכִיל וְרִבְקָה רְחִימַת יָת יַעֲקֹב:
@11 וּבַשִּׁיל יַעֲקֹב תַּבְשִׁילָא וַאֲתָא (נ'''י וְעַל) עֵשָׂו מִן חַקְלָא וְהוּא מְשַׁלְהֵי:
@12 וַאֲמַר עֵשָׂו לְיַעֲקֹב אַטְעֵמְנִי כְעַן מִן סִמּוֹקָא סִמּוֹקָא הָדֵין אֲרֵי מְשַׁלְהֵי אֲנָא עַל כֵּן קְרָא שְׁמֵהּ אֱדוֹם:
@13 וַאֲמַר יַעֲקֹב זַבִּין כְּיוֹם דִּלְהֵן יָת בְּכֵרוּתָךְ לִי:
@14 וַאֲמַר עֵשָׂו הָא אֲנָא אָזֵל לִמְמָת וּלְמָה דְּנָן לִי בְּכֵרוּתָא:
@15 וַאֲמַר יַעֲקֹב קַיֵּם לִי כְּיוֹם דִּלְהֵן וְקַיִּים לֵהּ וְזַבִּין יָת בְּכֵרוּתֵהּ לְיַעֲקֹב:
@16 וְיַעֲקֹב יְהַב לְעֵשָׂו לְחֵם וְתַבְשִׁיל דִּטְלוֹפְחִין וַאֲכַל וּשְׁתִי וְקָם וַאֲזָל וְשָׁט עֵשָׂו יָת בְּכֵרוּתָא:
@17 וַהֲוָה כַפְנָא בְּאַרְעָא בַּר מִכַּפְנָא קַדְמָאָה דִּי הֲוָה בְּיוֹמֵי אַבְרָהָם וַאֲזַל יִצְחָק לְוַת אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי לִגְרָר:
@18 וְאִתְגְּלִי לֵהּ יְיָ וַאֲמַר לָא תֵחוֹת לְמִצְרָיִם שְׁרֵי בְאַרְעָא דִּי אֵימַר לָךְ:
@19 דּוּר בְּאַרְעָא הָדָא וִיהֵי מֵימְרִי בְסַעְדָךְ וְאֵבָרְכִנָךְ אֲרֵי לָךְ וְלִבְנָיךְ אֶתֵּן יָת כָּל אַרְעָתָא הָאִלֵּין וְאָקֵם יָת קְיָמָא דִּי קַיֵּמִית לְאַבְרָהָם אֲבוּךְ:
@20 וְאַסְגֵּי יָת בְּנָיךְ סַגִּיאִין כְּכוֹכְבֵי שְׁמַיָּא וְאֶתֵּן לִבְנָיךְ יָת כָּל אַרְעָתָא הָאִלֵּין וְיִתְבָּרְכוּן בְּדִיל בְּנָךְ כֹּל עַמְמֵי אַרְעָא:
@21 חֳלַף דִּי קַבִּיל אַבְרָהָם בְּמֵימְרִי וּנְטַר מַטְּרַת מֵימְרִי פִּקּוֹדַי קְיָמַי וְאוֹרָיָתָי:
@22 וִיתֵב יִצְחָק בִּגְרָר:
@23 וּשְׁאִילוּ אֲנָשֵׁי אַתְרָא (עַל עֵיסַק אִתְּתֵהּ) לְאִתְּתֵהּ וַאֲמַר אֲחָתִי הִיא אֲרֵי דְחִיל לְמֵימַר אִתְּתִי דִּלְמָא יִקְטְּלֻנַּנִי אֲנָשֵׁי אַתְרָא עַל רִבְקָה אֲרֵי שַׁפִּירַת חֵיזוּ הִיא:
@24 וַהֲוָה כַּד סְגִיאוּ לֵהּ תַּמָּן יוֹמַיָּא וְאִסְתְּכִי אֲבִימֶלֶךְ מַלְכָּא דִּפְלִשְׁתָּאֵי מִן חֲרַכָּא וַחֲזָא וְהָא יִצְחָק מְחַיִּיךְ עִם רִבְקָה אִתְּתֵהּ:
@25 וּקְרָא אֲבִימֶלֶךְ לְיִצְחָק וַאֲמַר בְּרַם הָא אִתְּתָךְ הִיא וְאֶכְדֵּין אֲמַרְתָּ אֲחָתִי הִיא וַאֲמַר לֵהּ יִצְחָק אֲרֵי אֲמָרִית דִּלְמָא אֵימוּת עֲלַהּ:
@26 וַאֲמַר אֲבִימֶלֶךְ מָה דָא עֲבַדְתָּ לָנָא כִּזְעֵיר פּוֹן שָׁכִיב דִּמְיָחֵד בְּעַמָּא עִם אִתְּתָךְ וְאַיְתֵיתָא עֲלָנָא חוֹבָא:
@27 וּפַקִּיד אֲבִימֶלֶךְ יָת כָּל עַמָּא לְמֵימָר דְּיַנְזֵק לְגַבְרָא הָדֵין וּבְאִתְּתֵהּ אִתְקְטָלָא יִתְקְטֵּל:
@28 וּזְרַע יִצְחָק בְּאַרְעָא הַהִיא וְאַשְׁכַּח בְּשַׁתָּא הַהִיא עַל חַד מְאָה בִדְשַׁעֲרוֹהִי וּבָרְכֵהּ יְיָ:
@29 וּרְבָא גַּבְרָא וַאֲזַל אֲזִיל (נ''י סָגֵי) וְרָבֵי עַד דִּי רְבָא לַחֲדָא:
@30 וַהֲוָה לֵהּ גֵּיתֵי עָנָא וְגֵיתֵי תוֹרִין וּפָלְחָנָא (נ''י וַעֲבוּדָה) סַגְיָא וְקַנִּיאוּ בֵהּ פְּלִשְׁתָּאֵי:
@31 וְכָל בֵּירִין דִּי חֲפָרוּ עַבְדֵי אֲבוּהִי בְּיוֹמֵי אַבְרָהָם אֲבוּהִי טַמּוֹנוּן פְּלִשְׁתָּאֵי וּמְלוֹנוּן עַפְרָא:
@32 וַאֲמַר אֲבִימֶלֶךְ לְיִצְחָק אִזְּל מֵעִמָּנָא אֲרֵי תְקֵפְתָּא מִנָּנָא לַחֲדָא:
@33 וַאֲזַל מִתַּמָּן יִצְחָק וּשְׁרָא בְנַחֲלָא דִּגְרָר וִיתֵב תַּמָּן:
@34 וְתָב יִצְחָק וְחָפַר יָת בֵּירֵי דְמַיָּא דִּי חֲפָרוּ בְּיוֹמֵי אַבְרָהָם אֲבוּהִי וְטַּמּוֹנוּן פְּלִשְׁתָּאֵי בָּתַר דְּמִית אַבְרָהָם וּקְרָא לְהֵן שְׁמָהָן כִּשְׁמָהָן דִּי הֲוָה קָרֵי לְהֵן אֲבוּהִי:
@35 וַחֲפָרוּ עַבְדֵי יִצְחָק בְּנַחֲלָא וְאַשְׁכָּחוּ תַמָּן בֵּירָא דְּמַיִּין נָבְעִין:
@36 וּנְצוֹ רַעֲוָתָא דִּגְרָר עִם רַעֲוָתָא דְיִצְחָק לְמֵימַר דִּי לָנָא מַיָּא וּקְרָא שְׁמָא דְבֵירָא עִסְקָא אֲרֵי אִתְעַסִּיקוּ עִמֵּהּ:
@37 וַחֲפָרוּ בֵּירָא אָחֳרִי וּנְצוֹ אַף עֲלַהּ וּקְרָא שְׁמַהּ שִׂטְנָא:
@38 וְאִסְתַּלַּק מִתַּמָּן וַחֲפַר בֵּירָא אָחֳרִי וְלָא נְצוֹ עֲלַהּ וּקְרָא שְׁמַהּ רְחֹבוֹת וַאֲמַר אֲרֵי כְעַן אַפְתֵּי יְיָ לָנָא וְנִיפוּשׁ בְּאַרְעָא:
@39 וְאִסְתַּלַּק מִתַּמָּן לִבְּאֵר שָׁבַע:
@40 וְאִתְגְּלִי לֵהּ יְיָ בְּלֵילְיָא הַהוּא וַאֲמַר אֲנָא אֱלָהֵהּ דְּאַבְרָהָם אֲבוּךְ לָא תִדְחַל אֲרֵי בְסַעְדָּךְ מֵימְרִי וֶאֱבָרֵכִנָּךְ וְאַסְגֵּי יָת בְּנָיךְ בְּדִיל אַבְרָהָם עַבְדִּי:
@41 וּבְנָא תַמָּן מַדְבְּחָא וְצַלִּי בִּשְׁמָא דַּיְיָ וּפְרַס תַּמָּן מַשְׁכְּנֵהּ וּכְרוֹ תַמָּן עַבְדֵי יִצְחָק בֵּירָא:
@42 וַאֲבִימֶלֶךְ אֲזַל לְוָתֵהּ מִגְּרָר וְסִיעַת מֵרַחֲמוֹהִי וּפִיכֹל רַב חֵילֵהּ:
@43 וַאֲמַר לְהוֹן יִצְחָק מָה דֵּין אֲתֵיתוּן לְוָתִי וְאַתּוּן סְנֵיתוּן יָתִי וְשַׁלַּחְתּוּנִי מִלְּוָתְכוֹן:
@44 וַאֲמָרוּ מֶחֱזָא חֲזֵינָא אֲרֵי הֲוָה מֵימְרָא דַּיְיָ בִּסַעְדָּךְ וַאֲמַרְנָא תִּתְקַיַּם כְּעַן מוֹמָתָא דִּהֲוָה בֵין אֲבָהָתָנָא בֵּינָנָא וּבֵינָךְ וְנִגְזַר קְיָם עִמָּךְ:
@45 אִם תַּעְבֵּד עִמָּנָא בִּישָׁא כְּמָא דִּי לָא אַנְזִיקְנָךְ וּכְמָא דִּי עֲבַדְנָא עִמָךְ לְחוֹד טָב וַנְשַׁלְּחִנָּךְ בִּשְׁלָם אַתְּ כְּעַן בְּרִיכָא דַּיְיָ:
@46 וַעֲבַד לְהוֹן מִשְׁתְּיָא וַאֲכָלוּ וּשְׁתִיאוּ:
@47 וְאַקְדִימוּ בְצַפְרָא וְקַיִּימוּ גְּבַר לְאָחוּהִי וְשַׁלָּחִנוּן יִצְחָק וַאֲזָלוּ מִלְוָתֵהּ בִּשְׁלָם:
@48 וַהֲוָה בְּיוֹמָא הַהוּא וַאֲתוֹ עַבְדֵי יִצְחָק וְחַוִּיאוּ לֵהּ עַל עֵיסַק בֵּירָא דִּי חֲפָרוּ וַאֲמָרוּ לֵהּ אַשְׁכַּחְנָא מַיָּא:
@49 וּקְרָא יָתַהּ שִׁבְעָה עַל כֵּן שְׁמָא דְקַרְתָּא בְּאֵרָא דְשֶׁבַע (נ''י בְּאֵר שֶׁבַע) עַד יוֹמָא הָדֵין:
@50 וַהֲוָה עֵשָׂו בַּר אַרְבְּעִין שְׁנִין וּנְסִיב אִתְּתָא יָת יְהוּדִית בַּת בְּאֵרִי חִתָּאָה וְיָת בָּשְׂמַת בַּת אֵילוֹן חִתָּאָה:
@51 וַהֲוָאָה מְסָרְבָן וּמְרַגְּזָן עַל מֵימַר יִצְחָק וְרִבְקָה:
@52 וַהֲוָה כַּד סִיב יִצְחָק וְכָהֲיָּא עֵינוֹהִי מִלְּמֶחֱזֵי וּקְרָא יַת עֵשָׂו בְּרֵהּ רַבָּה וַאֲמַר לֵהּ בְּרִי וַאֲמַר לֵהּ הָא אָנָא:
@53 וַאֲמַר הָא כְעַן סֵיבִית לֵית אֲנָא יְדַע יוֹמָא דְאֵימוּת:
@54 וּכְעַן סַב כְּעַן זֵינָךְ סַיְפָךְ וְקַשְׁתָּךְ וּפוּק לְחַקְלָא וְצוּד לִי צֵידָא:
@55 וְעִבֵיד לִי תַבְשִׁילִין כְּמָא דִרְחֵימִית וְאָעֵל לִי וְאֵיכוּל בְּדִיל דִּי תְבָרֵכִנָּךְ נַפְשִׁי עַד לָא אֵימוּת:
@56 וְרִבְקָה שְׁמַעַת כַּד מַלִּיל יִצְחָק לְוַת עֵשָׂו בְּרֵהּ וַאֲזַל עֵשָׂו לְחַקְלָא לְמֵיצַד צֵידָא לְאַיְתָאָה:
@57 וְרִבְקָה אֲמָרַת לְוַת יַעֲקֹב בְּרַהּ לְמֵימָר הָא שְׁמָעִית יַת אֲבוּךְ מְמַלֵּל עִם עֵשָׂו:אַחוּךְ לְמֵימָר:
@58 אַיְתִי לִי צֵידָא וְעִבֵּיד לִי תַבְשִׁילִין וְאֵיכוּל וֶאֱבָרֵכִנָּךְ קֳדָם יְיָ קֳדָם מוֹתִי:
@59 וּכְעַן בְּרִי קַבֵּל מִנִי לְמָא דִי אֲנָא:מפַקֵד יָתָךְ:
@60 אִזֵיל כְּעַן לְוַת עָנָא וְסַב לִי מִתַּמָּן תְּרֵין גַדְיֵי (בַר) עִזְּין טָבָן וְאֶעְבֵּד יָתְהוֹן תַּבְשִׁילִין לְאָבוּךְ כְּמָא דִי רְחֵם:
@61 וְתַיְתִי (נ''י וְתָעֵל) לְאָבוּךְ וְיֵכוּל בְּדִיל דִּיְבָרְכִנָּךְ קֳדָם מוֹתֵהּ:
@62 וַאֲמַר יַעֲקֹב לְרִבְקָה אִמֵּהּ הָא עֵשָׂו אָחִי גְּבַר שַׂעֲרָן וַאֲנָא גְּבַר שְׁעִיעַ:
@63 מָאִים יְמֻשִּׁנַּנִי אַבָּא וְאֵהֵי בְעֵינוֹהִי כְּמִתְלָעָב וְאֵהֵי מַיְתֵי (נ''י וָאֱהִי מַיְתֵי) עֲלַי לְוָטִין וְלָא בִרְכָן:
@64 וַאֲמֶרֶת לֵהּ אִמֵּהּ עֲלַי אִתְאַמַּר בִּנְבוּאָה דְּלָא יֵיתוּן לְוָטַּיָּא עֲלָךְ בְּרִי בְּרַם קַבֵּל מִנִּי וְאִזְּיל סַב לִי:
@65 וַאֲזַל וּנְסִיב וְאַיְתִי לְאִמֵּהּ וַעֲבָדַת אִמֵּהּ תַּבְשִׁילִין כְּמָא דִּרְחֵם אֲבוּהִי:
@66 וּנְסִיבַת רִבְקָה יָת לְבוּשֵׁי עֵשָׂו בְּרַהּ רַבָּא דָּכְיָתָא דִּי עִמַּהּ בְּבֵיתָא וְאַלְבִּישַׁת יָת יַעֲקֹב בְּרַהּ זְעֵירָא:
@67 וְיָת מַשְׁכֵי גַּדְיֵי בַּר עִזֵּי אַלְבִּישַׁת עַל יְדוֹהִי וְעַל שְׁעִיעוּת צַוְרֵהּ:
@68 וִיהָבַת יָת תַּבְשִׁילַיָּא וְיָת לַחְמָא דִּי עֲבָדַת בִּידָא דְיַעֲקֹב בְּרַהּ:
@69 וְעַל לְוַת אֲבוּהִי וַאֲמַר אַבָּא וַאֲמַר הָא אֲנָא מָן אַתְּ בְּרִי:
@70 וַאֲמַר יַעֲקֹב לַאֲבוּהִי אֲנָא עֵשָׂו בּוּכְרָךְ עֲבָדִית כּמָא דִי מַלֵּילְתָּא עִמִּי (נ''י:לִי) קוּם כְּעַן אִסְתַּחַר וֶאֱכוּל מִצֵידִי בְּדִיל דִּי תבָרכִנַּנִּי נַפְשָׁךְ:
@71 וַאֲמַר יִצְחָק לִבְרֵהּ מָה דֵּין אוֹחֵיתָא לְאַשְׁכָּחָא בְּרִי וַאֲמַר אֲרֵי זַמִּין יְיָ אֱלָהָךְ קֳדָמַי:
@72 וַאֲמַר יִצְחָק לְיַעֲקֹב קְרֵיב כְּעַן וֶאֱמֻשִּׁנָּךְ בְּרִי הַאַתְּ דֵּין בְּרִי עֵשָׂו אִם לָא:
@73 וּקְרֵיב יַעֲקֹב לְוַת יִצְחָק אֲבוּהִי וּמָשְׁיֵהּ וַאֲמַר קָלָא קָלָא דְיַעֲקֹב וִידַיָּא יְדוֹהִי דְעֵשָׂו:
@74 וְלָא אִשְׁתְּמוֹדְעֵהּ אֲרֵי הֲוָאָה יְדוֹהִי כִּידֵי עֵשָׂו אֲחוּהִי שְׂעִירָן (נ''י שַׂעֲרַנְיָן) וּבָרְכֵהּ:
@75 וַאֲמַר אַתְּ דֵּין בְּרִי עֵשָׂו וַאֲמַר הָא אֲנָא:
@76 וַאֲמַר קָרֵיב קֳדָמַי וְאֵיכוּל מִצֵידָא דִּבְרִי בְּדִיל דִּי תְבָרְכִנָּךְ נַפְשִׁי וְקָרֵיב לֵהּ וַאֲכַל וְאַיְתִי (נ''י וְאָעֵל) לֵהּ חַמְרָא וּשְׁתִי:
@77 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי קְרֵיב כְּעַן וּנְשַׁק לִי (נ''י וְשַׁק לִי) בְּרִי:
@78 וּקְרֵב וּנְשַׁק לֵהּ וַאֲרַח יָת רֵיחָא דִּלְבוּשׁוֹהִי וּבָרְכֵהּ וַאֲמַר חֲזֵי רֵיחָא דִּבְרִי כְּרֵיחָא דְחַקְלָא דִּי בָרֲכֵהּ יְיָ:
@79 וְיִתֶּן לָךְ יְיָ מִטַּלָּא דִּשְׁמַיָּא וּמִטּוּבָא דְאַרְעָא וּסְגִיאוּת (נ''י וְסַגְיוּת) עִיבוּר וַחֲמָר:
@80 יִפְלְחֻנָּךְ עַמְמִין וְיִשְׁתַּעְבְּדוּן לָךְ מַלְכְּוָן הֱוֵי רַב לְאַחָיךְ וְיִסְגְּדוּן לָךְ בְּנֵי אִמָּךְ מְלַטְטָיךְ יְהוֹן לִיטִין וּמְבָרֲכָיךְ יְהוֹן בְּרִיכִין:
@81 וַהֲוָה כַּד שֵׁיצֵי יִצְחָק לְבָרָכָא יָת יַעֲקֹב וַהֲוָה בְּרַם מִפַּק נְפַק יַעֲקֹב מִלְּוַת אַפֵּי יִצְחָק אֲבוּהִי וְעֵשָׂו אֲחוּהִי אָתָא (נ''י עַל) מִצֵידֵהּ:
@82 וַעֲבַד אַף הוּא תַּבְשִׁילִין וְאָעֵיל לְוַת אֲבוּהִי וַאֲמַר לַאֲבוּהִי יָקוּם אַבָּא וְיֵכוּל מִצֵידָא דִּבְרֵהּ בְּדִיל דִּי תְבָרְכִנַּנִּי נַפְשָׁךְ:
@83 וַאֲמַר לֵהּ יִצְחָק אֲבוּהִי מָן אָתְּ וַאֲמַר אֲנָא בְּרָךְ בּוּכְרָךְ עֵשָׂו:
@84 וּתְוָה יִצְחָק תִּוְהָא רַבָּא עַד לַחֲדָא וַאֲמַר מָן הוּא דֵּיכִי דְצָד צֵידָא וְאָעֵיל לִי וַאֲכָלִית מִכֹּלָּא עַד לָא תֵיעוֹל וּבָרֵכִתֵּהּ אַף בְּרִיךְ יְהֵי:
@85 כַּד שְׁמַע עֵשָׂו יָת פִּתְגָּמֵי אֲבוּהִי וּצְוַח צִוְחָא רַבָּא וּמְרִירָא עַד לַחֲדָא וַאֲמַר לַאֲבוּהִי בָּרֵכְנִי אַף אֲנָא (נ''י לִי) אַבָּא:
@86 וַאֲמַר עַל אָחוּךְ בְּחָכְמְתָא וְקַבִּיל בִּרְכְּתָךְ:
@87 וַאֲמַר יָאוּת קְרָא שְׁמֵהּ יַעֲקֹב וְכָמַנִי דְּנָן תַּרְתֵּין זִמְנִין יָת בְּכֵירוּתִי נְסִיב וְהָא כְּעַן קַבִּיל בִּרְכְּתִי וַאֲמַר הֲלָא שְׁבַקְתָּ לִי בִּרְכְּתָא:
@88 וַאֲתֵיב יִצְחָק וַאֲמַר לְעֵשָׂו הָא רַב שַׁוִּתֵּהּ לָךְ (נ''י עִלַּוָּךְ) וְיָת כָּל אֲחוֹהִי יְהָבִית לֵהּ לְעַבְדִּין וְעִיבוּר וַחֲמָר סְעִדְתֵּהּ וְלָךְ הָכָא מָה אֶעְבֵּיד בְּרִי:
@89 וַאֲמַר עֵשָׂו לַאֲבוּהִי הֲבִרְכְּתָא חֲדָא הִיא לָךְ אַבָּא בָּרֵךְ לִי אַף אֲנָא אַבָּא וַאֲרֵים עֵשָׂו קָלֵהּ וּבְכָא:
@90 וַאֲתֵיב יִצְחָק אֲבוּהִי וַאֲמַר לֵהּ הָא מִטּוּבָא דְאַרְעָא יְהֵא מוֹתְבָךְ וּמִטַּלָּא דִּשְׁמַיָּא מִלְּעֵלָא:
@91 וְעַל חַרְבָּךְ תֵּיחֵי וְיָת אָחוּךְ תִּפְלָח וִיהֵי כַּד יַעְבְּרוּן בְּנוֹהִי עַל פִּתְגָּמֵי אוֹרַיְתָא וְתַעְדִּי נִירֵהּ מֵעַל צַוְרָךְ:
@92 וּנְטַר עֵשָׂו דְּבָבוּ לְיַעֲקֹב עַל בִּרְכְּתָא דִּי בָרְכֵהּ אֲבוּהִי וַאֲמַר עֵשָׂו בְּלִבֵּהּ יִקְרְבוּן יוֹמֵי אֶבְלֵי דְאַבָּא וְאֶקְטוֹל יָת יַעֲקֹב אָחִי:
@93 וְאִתְחַוָּה לְרִבְקָה יָת פִּתְגָּמֵי עֵשָׂו בְּרַהּ רַבָּא וּשְׁלָחַת וּקְרַת לְיַעֲקֹב בְּרַהּ זְעֵירָא וַאֲמֶרֶת לֵהּ הָא עֵשָׂו אָחוּךְ כָּמִן לָךְ לְמִקְטְלָךְ:
@94 וּכְעַן בְּרִי קַבֵּל מִנִּי וְקוּם אִזֵּיל לָךְ לְוַת לָבָן אָחִי לְחָרָן:
@95 וְתֵתֵיב עִמֵּהּ יוֹמִין זְעֵירִין עַד דִּיתוּב רוּגְזָא דְאָחוּךְ:
@96 עַד דִּיתוּב רוּגְזָא דְאָחוּךְ מִנָּךְ וְיִתְנְשֵׁי יָת דִּי עֲבַדְתָּ לֵהּ וְאֶשְׁלַח וְאֶדְבְּרִנָּךְ מִתַּמָּן לְמָה אֶתְכַּל אַף תַּרְוֵיכוֹן יוֹמָא חָד:
@97 וַאֲמֶרֶת רִבְקָה לְיִצְחָק עָקִית בְּחַיַּי מִן קֳדָם בְּנַת חִתָּאָה אִם נְסִיב יַעֲקֹב אִתְּתָא מִבְּנַת חִתָּאָה כְאִלֵּין מִבְּנַת אַרְעָא לְמָה לִי חַיִּים:
@98 וּקְרָא יִצְחָק לְיַעֲקֹב וּבָרִיךְ יָתֵהּ וּפַקְדֵהּ וַאֲמַר לֵהּ לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@99 קוּם אִזֵּיל לְפַדַּן אֲרָם לְבֵית בְּתוּאֵל אֲבוּהָא דְאִמָּךְ וְסַב לָךְ מִתַּמָּן אִתְּתָא מִבְּנַת לָבָן אֲחוּהָא דְאִמָּךְ:
@100 וְאֵל שַׁדַּי יְבָרֵךְ יָתָךְ וְיַפְּשָׁךְ וְיַסְגִּנָּךְ וּתְהֵי לְכִנְשַׁת שִׁבְטִין:
@101 וְיִתֶּן לָךְ יָת בִּרְכְּתָא דְאַבְרָהָם לָךְ וְלִבְנָיךְ עִמָּךְ לְמֵירְתָךְ יָת אֲרַע תּוֹתָבוּתָךְ דִּי יְהַב יְיָ לְאַבְרָהָם:
@102 וּשְׁלַח יִצְחָק יָת יַעֲקֹב וַאֲזַל לְפַדַּן אֲרָם לְוַת לָבָן בַּר בְּתוּאֵל אֲרַמָּאָה אֲחוּהָא דְרִבְקָה אִמֵּהּ דְּיַעֲקֹב וְעֵשָׂו:
@103 וַחֲזָא עֵשָׂו אֲרֵי בָרִיךְ יִצְחָק יָת יַעֲקֹב וְשַׁלַּח יָתֵהּ לְפַדַּן אֲרָם לְמִסַּב לֵהּ מִתַּמָּן אִתְּתָא כַּד בָּרִיךְ יָתֵהּ וּפַקֵּיד עֲלוֹהִי לְמֵימַר לָא תִסַּב אִתְּתָא מִבְּנַת כְּנָעַן:
@104 וְקַבִּיל יַעֲקֹב מִן אֲבוּהִי וּמִן אִמֵּהּ וַאֲזַל לְפַדַּן אֲרָם:
@105 וַחֲזָא עֵשָׂו אֲרֵי בִישָׁא בְּנַת כְּנָעַן בְּעֵינֵי יִצְחָק אֲבוּהִי:
@106 וַאֲזַל עֵשָׂו לְוַת יִשְׁמָעֵאל וּנְסִיב יָת מַחֲלַת בַּת יִשְׁמָעֵאל בַּר אַבְרָהָם אֲחָתֵהּ דִּנְבָיוֹת עַל נְשׁוֹהִי לֵהּ לְאִנְתּוּ: ססס:

@1 **ואלה תולדות יצחק.** יעקב ועשו האמורים בפרשה: **אברהם הוליד את יצחק.** על ידי שכתב הכתוב יצחק בן אברהם הזקק לומר אברהם הוליד את יצחק, לפי שהיו ליצני הדור אומרים מאבימלך נתעברה שרה, שהרי כמה שנים שהתה עם אברהם ולא נתעברה המנו, מה עשה הקדוש ברוך הוא, צר קלסתר פניו של יצחק דומה לאברהם, והעידו הכל אברהם הוליד את יצחק, וזהו שכתב כאן יצחק בן אברהם היה, שהרי עדות יש שאברהם הוליד את יצחק:
@2 **בן ארבעים שנה.** שהרי כשבא אברהם מהר המוריה נתבשר שנלדה רבקה, ויצחק היה בן שלשים ושבע שנה, שהרי בו בפרק מתה שרה, ומשנלד יצחק עד העקידה שמתה שרה שלשים ושבע שנה, ובת תשעים היתה כשנלד יצחק, ובת מאה עשרים ושבע כשמתה, שנאמר (כג א) ויהיו חיי שרה וגו' , הרי ליצחק שלשים ושבע שנים ובו בפרק נלדה רבקה, המתין לה עד שתהא ראויה לביאה שלש שנים ונשאה: **בת בתואל מפדן ארם אחות לבן.** וכי עדיין לא נכתב שהיא בת בתואל ואחות לבן ומפדן ארם, אלא להגיד שבחה שהיתה בת רשע ואחות רשע ומקומה אנשי רשע, ולא למדה ממעשיהם: **מפדן ארם.** על שם ששני ארם היו, ארם נהרים וארם צובה, קורא אותו פדן, לשון (שמואל א' יא ז) צמד בקר, תרגום פדן תורין. ויש פותרין פדן ארם כמו (הושע יב יג) שדה ארם, שבלשון ישמעאל קורין לשדה פדן:
@3 **ויעתר.** הרבה והפציר בתפלה: **ויעתר לו.** נתפצר ונתפייס ונתפתה לו, ואומר אני כל לשון עתר לשון הפצרה ורבוי הוא וכן (יחזקאל ח יא) ועתר ענן הקטרת, מרבית עלית העשן, וכן (שם לה יג) והעתרתם עלי דבריכם, וכן (משלי כז ו) נעתרות נשיקות שונא, דומות למרבות והנם למשא. אינקריישימינ''ט בלע''ז : **לנכח אשתו.** זה עומד בזוית זו ומתפלל, וזו עומדת בזוית זו ומתפללת: **ויעתר לו.** לו ולא לה, שאין דומה תפלת צדיק בן צדיק לתפלת צדיק בן רשע לפיכך לו ולא לה:
@4 **ויתרוצצו.** על כרחך המקרא הזה אומר דרשני, שסתם מה היא רציצה זו וכתב אם כן למה זה אנכי. רבותינו דרשוהו לשון ריצה, כשהיתה עוברת על פתחי תורה של שם ועבר יעקב רץ ומפרכס לצאת, עוברת על פתחי עבודה זרה עשו מפרכס לצאת. דבר אחר מתרוצצים זה עם זה ומריבים בנחלת שני עולמות: **ותאמר אם כן.** גדול צער העבור: **למה זה אנכי.** מתאוה ומתפללת על הריון: **ותלך לדרש.** לבית מדרשו של שם: **לדרש את ה'.** שיגיד לה מה תהא בסופה:
@5 **ויאמר ה' לה.** על ידי שליח, לשם נאמר ברוח הקודש והוא אמר לה: **שני גוים בבטנך.** גיים כתיב, אלו אנטונינוס ורבי, שלא פסקו מעל שלחנם לא צנון ולא חזרת לא בימות החמה ולא בימות הגשמים: **ושני לאמים.** אין לאום אלא מלכות: **ממעיך יפרדו.** מן המעים הם נפרדים, זה לרשעו וזה לתמו: **מלאם יאמץ.** לא ישוו בגדולה, כשזה קם זה נופל, וכן הוא אומר (יחזקאל כו ב) אמלאה החרבה, לא נתמלאה צור אלא מחרבנה של ירושלים:
@6 **וימלאו ימיה.** אבל בתמר כתיב (להלן לח כז) ויהי בעת לדתה. שלא מלאו ימיה כי לשבעה חדשים ילדתם: **והנה תומם.** חסר, ובתמר תאומים מלא לפי ששניהם צדיקים, אבל כאן אחד צדיק ואחד רשע:
@7 **אדמוני.** סימן הוא שיהא שופך דמים: **כלו כאדרת שער.** מלא שער כטלית של צמר המלאה שער פלוקייד''א בלע''ז : **ויקראו שמו עשו.** הכל קראו לו כן, לפי שהיה נעשה ונגמר בשערו כבן שנים הרבה:
@8 **ואחרי כן יצא אחיו** וגו' **.** שמעתי מדרש אגדה הדורשו לפי פשוטו, בדין היה אוחז בו לעכבו, יעקב נצר מטפה ראשונה ועשו מן השניה, צא ולמד משפופרת שפיה קצרה, תן לה שתי אבנים זו תחת זו, הנכנסת ראשונה תצא אחרונה, והנכנסת אחרונה תצא ראשונה, נמצא עשו הנצר באחרונה יצא ראשון, ויעקב שנצר ראשונה יצא אחרון, ויעקב בא לעכבו שיהא ראשון ללידה כראשון ליצירה, ויפטור את רחמה, ויטול את הבכורה מן הדין: **בעקב עשו.** סימן שאין זה מספיק לגמור מלכותו עד שזה עומד ונוטלה המנו: **ויקרא שמו יעקב.** הקדוש ברוך הוא. דבר אחר אביו קרא לו יעקב על שם אחיזת העקב: **בן ששים שנה.** עשר שנים משנשאה עד שנעשית בת שלש עשרה שנה וראויה להריון ועשר שנים הללו צפה והמתין לה כמו שעשה אביו לשרה, כיון שלא נתעברה ידע שהיא עקרה והתפלל עליה. ושפחה לא רצה לשא, לפי שנתקדש בהר המוריה להיות עולה תמימה:
@9 **ויגדלו הנערים ויהי עשו.** כל זמן שהיו קטנים לא היו נכרים במעשיהם ואין אדם מדקדק בהם מה טיבם, כיון שנעשו בני שלש עשרה שנה זה פרש לבתי מדרשות וזה פרש לעבודה זרה: **ידע ציד.** לצוד ולרמות את אביו בפיו, ושואלו אבא היאך מעשרין את המלח ואת התבן, כסבור אביו שהוא מדקדק במצות: **איש שדה.** כמשמעו אדם בטל וצודה בקשתו חיות ועופות: **תם.** אינו בקי בכל אלה, אלא כלבו כן פיו. מי שאינו חריף לרמות קרוי תם: **ישב אהלים.** אהלו של שם ואהלו של עבר:
@10 **בפיו.** כתרגומו בפיו של יצחק. ומדרשו בפיו של עשו שהיה צד אותו ומרמהו בדבריו:
@11 **ויזד.** לשון בשול, כתרגומו: **והוא עיף.** ברציחה, כמה דתימא (ירמיה ד לא) כי עיפה נפשי להורגים:
@12 **הלעיטני.** אפתח פי ושפוך הרבה לתוכו, כמו ששנינו: אין אובסין את הגמל אבל מלעיטין אותו (שבת קנה:) : **מן האדם האדם.** עדשים אדמות, ואותו היום מת אברהם שלא יראה את עשו בן בנו יוצא לתרבות רעה, ואין זו שיבה טובה שהבטיחו הקדוש ברוך הוא, לפיכך קצר הקדוש ברוך הוא חמש שנים משנותיו, שיצחק חי מאה ושמונים שנה וזה מאה שבעים וחמש שנה, ובשל יעקב עדשים להברות את האבל. ולמה עדשים, שדומות לגלגל שהאבלות גלגל החוזר בעולם (ועוד מה עדשים אין להם פה כך האבל אין לו פה שאסור לדבר. לפיכך המנהג להברות את האבל בתחלת מאכלו ביצים שהם עגלים ואין להם פה, כך אבל אין לו פה כדאמרינן במועד קטן (כא ב) אבל כל שלשה ימים הראשונים אינו משיב שלום לכל אדם וכל שכן שאינו שואל בתחלה, משלשה ועד שבעה משיב ואינו שואל וכו' ) :
@13 **מכרה כיום.** כתרגומו, כיום דילהן, כיום שהוא ברור, כך מכור לי מכירה ברורה: **בכרתך.** לפי שהעבודה בבכורות, אמר יעקב אין רשע זה כדאי שיקריב להקדוש ברוך הוא:
@14 **הנה אנכי הולך למות.** (מתנודדת והולכת היא הבכורה שלא תהא כל עת העבודה בבכורות כי שבט לוי יטל אותה ועוד) אמר עשו מה טיבה של עבודה זו, אמר לו כמה אזהרות וענשין ומיתות תלוין בה, כאותה ששנינו אלו הן שבמיתה שתויי יין, ופרועי ראש. אמר אני הולך למות על ידה, אם כן מה חפץ לי בה:
@16 **ויבז עשו.** העיד הכתוב על רשעו שבזה עבודתו של מקום:
@18 **אל תרד מצרימה.** שהיה דעתו לרדת מצרימה כמו שירד אביו בימי הרעב, אמר לו אל תרד מצרימה שאתה עולה תמימה, ואין חוצה לארץ כדאי לך:
@19 **האל.** כמו האלה:
@20 **והתברכו בזרעך.** אדם אומר לבנו יהא זרעך כזרעו של יצחק, וכן בכל המקרא. וזה אב לכלן (להלן מח כ) בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה, ואף לענין הקללה מצינו כן (במדבר ה כז) והיתה האשה לאלה, שהמקלל שונאו אומר תהא כפלונית, וכן (ישעיה סה טו) והנחתם שמכם לשבועה לבחירי, שהנשבע אומר אהא כפלוני אם עשיתי כך וכך:
@21 **שמע אברהם בקלי.** כשנסיתי אותו: **וישמר משמרתי.** גזרות להרחקה על אזהרות שבתורה, כגון שניות לעריות ושבות לשבת: **מצותי.** דברים שאלו לא נכתבו ראויין הם להצטוות כגון גזל ושפיכות דמים: **חקותי.** דברים שיצר הרע ואמות העולם משיבין עליהן כגון אכילת חזיר ולבישת שעטנז שאין טעם בדבר אלא גזרת המלך וחקותיו על עבדיו: **ותורתי.** להביא תורה שבעל פה, הלכה למשה מסיני:
@23 **לאשתו.** על אשתו, כמו (לעיל כ יג) אמרי לי אחי הוא:
@24 **כי ארכו.** אמר מעתה אין לי לדאוג מאחר שלא אנסוה עד עכשיו, ולא נזהר להיות נשמר: **וישקף אבימלך** וגו' **.** שראהו משמש מטתו:
@26 **אחד העם.** המיחד בעם זה המלך: **והבאת עלינו אשם.** אם שכב, כבר הבאת עלינו אשם:
@28 **בארץ ההיא.** אף על פי שאינה חשובה כארץ ישראל עצמה, כארץ שבעה גוים: **בשנה ההיא.** אף על פי שאינה כתקנה, שהיתה שנת רעבון: **בארץ ההיא בשנה ההיא.** שניהם למה, לומר שהארץ קשה והשנה קשה: **מאה שערים.** שאמדוה כמה ראויה לעשות ועשתה על אחת מאה ממה שאמדוה. ורבותינו אמרו אומד זה למעשרות היה:
@29 **כי גדל מאד.** שהיו אומרים זבל פרדותיו של יצחק ולא כספו וזהבו של אבימלך:
@30 **ועבדה רבה.** פעלה רבה, בלשון לע''ז אובריינ''א [מכלול העבודות] עבודה משמע עבודה אחת, עבדה משמע פעלה רבה:
@31 **סתמום פלשתים.** מפני שאמרו תקלה הם לנו מפני הגיסות הבאות עלינו. טמונין פלשתאי לשון סתימה, ובלשון משנה (פסחים מב א) מטמטם את הלב:
@33 **בנחל גרר.** רחוק מן העיר:
@34 **וישב ויחפר.** הבארות אשר חפרו בימי אברהם אביו. ופלשתים סתמום, מקדם שנסע יצחק מגרר חזר וחפרן:
@36 **עשק.** ערעור: **כי התעשקו עמו.** נתעשקו עמו עליה במריבה וערעור:
@37 **שטנה.** נוישימונ''ט [נזק]:
@38 **ופרינו בארץ.** כתרגומו ונפוש בארעא:
@42 **ואחזת מרעהו.** כתרגומו וסיעת מרחמוהי, סיעת מאוהביו. ויש פותרין מרעהו מ' מיסוד התבה, כמו (שופטים יד יא) שלשים מרעים דשמשון, כדי שתהיה תבת ואחזת דבוקה, אבל אין דרך ארץ לדבר על המלכות כן סיעת אוהביו, שאם כן כל סיעת אוהביו הוליך עמו ולא היה לו אלא סיעה אחת של אוהבים, לכן יש לפתרו כלשון הראשון. ואל תתמה על תי''ו של ואחזת ואף על פי שאין התבה סמוכה, יש דגמתה במקרא (תהלים ס יג) עזרת מצר, (ישעיה נא כא) ושכורת ולא מיין: **אחזת.** לשון קבוצה ואגודה שנאחזין יחד:
@44 **ראו ראינו.** ראה באביך ראינו בך: **תהי נא אלה בינותינו** וגו' **.** האלה אשר בינותינו מימי אביך, תהי גם עתה בינינו וביניך:
@45 **לא נגענוך.** כשאמרנו (לעיל פסוק טז) לך מעמנו: **אתה.** גם אתה עשה עמנו כמו כן:
@49 **שבעה.** על שם הברית:
@50 **בן ארבעים שנה.** עשו היה נמשל לחזיר, שנאמר (תהלים פ יד) יכרסמנה חזיר מיער, החזיר הזה כשהוא שוכב פושט טלפיו לומר ראו שאני טהור, כך אלו [אלופי עשו] גוזלים וחומסים ומראים עצמם כשרים. כל ארבעים שנה היה עשו צד נשים מתחת בעליהן ומענה אותם, כשהיה בן ארבעים אמר אבא בן ארבעים שנה נשא אשה, אף אני כן:
@51 **מרת רוח.** לשון המראות רוח, כמו (דברים ט כד) ממרים הייתם כל מעשיהן היו לעצבון: **ליצחק ולרבקה.** שהיו עובדות עבודה זרה:
@52 **ותכהין.** בעשנן של אלו. דבר אחר כשנעקד על גבי המזבח והיה אביו רוצה לשחטו, באותה שעה נפתחו השמים וראו מלאכי השרת והיו בוכים וירדו דמעותיהם ונפלו על עיניו, לפיכך כהו עיניו. דבר אחר כדי שיטול יעקב את הברכות:
@53 **לא ידעתי יום מותי.** אמר רבי יהושע בן קרחה, אם מגיע אדם לפרק אבותיו ידאג חמש שנים לפניהם וחמש לאחר כן, ויצחק היה בן מאה עשרים ושלש, אמר שמא לפרק אמי אני מגיע, והיא מתה בת מאה עשרים ושבע והריני בן חמש שנים סמוך לפרקה, לפיכך לא ידעתי יום מותי, שמא לפרק אמי, שמא לפרק אבא:
@54 **תליך.** חרבך שדרך לתלותה: **שא נא.** לשון השחזה כאותה ששנינו (ביצה כח א) אין משחיזין את הסכין אבל משיאה על גבי חברתה, חדד סכינך ושחוט יפה, שלא תאכילני נבלה: **וצודה לי.** מן ההפקר ולא מן הגזל:
@56 **לצוד ציד להביא.** מהו להביא, אם לא ימצא ציד יביא מן הגזל:
@58 **לפני ה'.** ברשותו שיסכים על ידי:
@60 **וקח לי.** משלי הם ואינם גזל, שכך כתב לה יצחק בכתבתה לטול שני גדיי עזים בכל יום: **שני גדיי עזים.** וכי שני גדיי עזים היה מאכלו של יצחק, אלא האחד הקריב לפסחו והאחד עשה מטעמים. בפרקי דרבי אליעזר (פרק לב) : **כאשר אהב.** כי טעם הגדי כטעם הצבי:
@62 **איש שער.** בעל שער:
@63 **ימשני.** כמו (דברים כח כט) ממשש בצהרים:
@66 **החמודות.** הנקיות, כתרגומו דכייתא. דבר אחר שחמד אותן מן נמרוד: **אשר אתה בבית.** והלא כמה נשים היו לו והוא מפקיד אצל אמו, אלא שהיה בקי במעשיהן וחושדן:
@70 **אנכי עשו בכרך.** אנכי המביא לך, ועשו הוא בכרך: **עשיתי.** כמה דברים כאשר דברת אלי: **שבה.** לשון מיסב על השלחן, לכך מתורגם אסתחר:
@72 **גשה נא ואמשך.** אמר יצחק בלבו אין דרך עשו להיות שם שמים שגור בפיו, וזה אמר (פסוק כ) כי הקרה ה' אלהיך:
@73 **קול יעקב.** שמדבר בלשון תחנונים (פסוק יט) קום נא, אבל עשו בלשון קנטוריא דבר (פסוק לא) יקום אבי:
@75 **ויאמר אני.** לא אמר אני עשו אלא אני:
@78 **וירח** וגו' **.** והלא אין ריח רע יותר משטף העזים, אלא מלמד שנכנסה עמו ריח גן עדן: **כריח שדה אשר ברכו ה'.** שנתן בו ריח טוב, וזה שדה תפוחים, כן דרשו רבותינו זכרונם לברכה:
@79 **ויתן לך.** יתן ויחזור ויתן. ולפי פשוטו מוסב לענין הראשון ראה ריח בני, שנתן לו הקדוש ברוך הוא, כריח שדה וגו' ועוד יתן לך מטל השמים וגו' : **האלהים.** מהו האלהים, בדין, אם ראוי לך יתן לך, ואם לאו לא יתן לך, אבל לעשו אמר משמני הארץ יהיה מושבך, בין צדיק בין רשע יתן לך, וממנו למד שלמה כשעשה הבית וסדר תפלתו, ישראל שהוא בעל אמונה ומצדיק עליו את הדין לא יקרא עליך תגר, לפיכך, (מ''א ח לט) ונתת לאיש ככל דרכיו אשר תדע את לבבו, אבל נכרי מחסר אמנה, לפיכך אמר (שם שם מג) אתה תשמע השמים וגו' ועשית ככל אשר יקרא אליך הנכרי, בין ראוי בין שאינו ראוי תן לו, כדי שלא יקרא עליך תגר: **מטל השמים.** כמשמעו, ומדרש אגדה יש להרבה פנים:
@80 **בני אמך.** ויעקב אמר ליהודה (להלן מט ח) בני אביך, לפי שהיו לו בנים מכמה אמהות, וכאן שלא נשא אלא אשה אחת אמר בני אמך: **ארריך ארור ומברכיך ברוך.** ובבלעם הוא אומר (במדבר כד ט) מברכיך ברוך ואורריך ארור. הצדיקים תחלתם יסורים וסופן שלוה, ואורריהם ומצעריהם קודמים למברכיהם, לפיכך יצחק הקדים קללת אוררים לברכת מברכים. והרשעים תחלתן שלוה וסופן, יסורין לפיכך בלעם הקדים ברכה לקללה:
@81 **יצא יצא.** זה יוצא וזה בא:
@84 **ויחרד.** כתרגומו ותוה לשון תימה. ומדרשו ראה גיהנם פתוחה מתחתיו: **מי אפוא.** לשון לעצמו, משמש עם כמה דברים. איפוא, איה פה, מי הוא ואיפוא הוא הצד ציד: **ואכל מכל.** מכל טעמים שבקשתי לטעום טעמתי בו: **גם ברוך יהיה.** שלא תאמר אלולי שרמה יעקב לאביו לא נטל את הברכות, לכך הסכים וברכו מדעתו:
@86 **במרמה.** בחכמה:
@87 **הכי קרא שמו.** לשון תימה הוא, כמו (לקמן כט טו) הכי אחי אתה, שמא לכך נקרא שמו יעקב על שם סופו שהוא עתיד לעקבני. תנחומא (תנחומא ישן כג) למה חרד יצחק, אמר שמא עון יש בי שברכתי הקטן לפני הגדול, ושניתי סדר היחס. התחיל עשו מצעק ויעקבני זה פעמים, אמר לו אביו מה עשה לך, אמר לו את בכורתי לקח, אמר בכך הייתי מצר וחרד שמא עברתי על שורת הדין, עכשיו לבכור ברכתי, גם ברוך יהיה: **ויעקבני.** כתרגומו וכמני, ארבני. וארב, וכמן. ויש מתרגמין וחכמני נתחכם לי: **אצלת.** לשון הפרשה, כמו (במדבר יא כה) ויאצל:
@88 **הן גביר.** ברכה זו שביעית היא והוא עושה אותה ראשונה, אלא אמר לו מה תועלת לך בברכה, אם תקנה נכסים שלו הם, שהרי גביר שמתיו לך ומה שקנה עבד קנה רבו: **ולכה אפוא מה אעשה.** איה פה אבקש מה לעשות לך:
@89 **הברכה אחת.** ה''א זו משמשת לשון תימה, כמו (במדבר יג יט) הבמחנים, (במדבר יג כ) השמנה היא, (ש''ב ג לג) הכמות נבל:
@90 **משמני הארץ** וגו' **.** זו איטליה של יון:
@91 **ועל חרבך.** כמו בחרבך, יש על שהוא במקום אות ב', כמו (יחזקאל לג כו) עמדתם על חרבכם בחרבכם, (שמות ו כו) על צבאותם בצבאותם: **והיה כאשר תריד.** לשון צער, כמו (תהלים נה ג) אריד בשיחי, כלומר כשיעברו ישראל את התורה, ויהיה לך פתחון פה להצטער על הברכות שנטל, ופרקת עלו וגו' :
@92 **יקרבו ימי אבל אבי.** כמשמעו, שלא אצער את אבא. ומדרש אגדה לכמה פנים יש:
@93 **ויגד לרבקה.** ברוח הקודש הגד לה מה שעשו מהרהר בלבו: **מתנחם לך.** נחם על האחוה לחשוב מחשבה אחרת להתנכר לך ולהרגך. ומדרש אגדה כבר אתה מת בעיניו ושתה עליך כוס של תנחומים. ולפי פשוטו לשון תנחומים, מתנחם הוא על הברכות בהריגתך:
@95 **אחדים.** מועטים:
@96 **למה אשכל.** אהיה שכולה משניכם. הקובר את בניו קרוי שכול. וכן ביעקב אמר (להלן מג יד) כאשר שכלתי שכלתי: **גם שניכם.** אם יקום עליך ואתה תהרגנו יעמדו בניו ויהרגוך, ורוח הקדש נזרקה בה ונתנבאה שביום אחד ימותו, כמו שמפורש בפרק המקנא לאשתו (סוטה יג א) :
@97 **קצתי בחיי.** מאסתי בחיי:
@99 **פדנה.** כמו לפדן: **ביתה בתואל.** לבית בתואל. כל תבה שצריכה למ''ד בתחלתה הטיל לה ה''א בסופה:
@100 **ואל שדי.** מי שדי בברכותיו למתברכין מפיו יברך אותך:
@101 **את ברכת אברהם.** שאמר לו (לעיל יב ב) ואעשך לגוי גדול, (שם כב יח) והתברכו בזרעך. יהיו אותן ברכות האמורות בשבילך, ממך יצא אותו הגוי ואותו הזרע המבורך:
@102 **אם יעקב ועשו.** איני יודע מה מלמדנו:
@104 **וישמע יעקב.** מחבר לענין של מעלה וירא עשו כי ברך יצחק וגו' וכי שלח אותו פדנה ארם, וכי שמע יעקב אל אביו והלך פדנה ארם וכי רעות בנות כנען, והלך גם הוא אל ישמעאל:
@106 **אחות נביות.** ממשמע שנאמר (לעיל כה יג) בת ישמעאל איני יודע שהיא אחות נביות, אלא למדנו שמת ישמעאל משיעדה לעשו קודם נשואיה והשיאה נביות אחיה. ולמדנו שהיה יעקב באותו הפרק בן ששים ושלש שנים, שהרי ישמעאל בן שבעים וארבע שנים היה כשנלד יעקב, ארבע עשרה שנה היה גדול ישמעאל מיצחק, ויצחק בן ששים שנה בלדת אותם הרי שבעים וארבע, ושנותיו היו מאה שלשים ושבע, שנאמר (שם יז) ואלה שני חיי ישמעאל וגו' , נמצא יעקב כשמת ישמעאל בן ששים ושלש שנים היה, ולמדנו מכאן שנטמן בבית עבר ארבע עשרה שנה ואחר כך הלך לחרן, שהרי לא שהה בבית לבן שלפני לידתו של יוסף אלא ארבע עשרה שנה, שנאמר (שם לא מא) עבדתיך ארבע עשרה שנה בשתי בנותיך ושש שנים בצאנך ושכר הצאן משנלד יוסף היה, שנאמר (שם ל כה) ויהי כאשר ילדה רחל את יוסף וגו' , ויוסף בן שלשים שנה היה כשמלך, ומשם עד שירד יעקב למצרים תשע שנים, שבע של שבע ושתים של רעב, ויעקב אמר לפרעה (שם מז ט) ימי שני מגורי שלשים ומאת שנה. צא וחשוב ארבע עשרה שלפני לידת יוסף, ושלשים של יוסף, ותשע משמלך עד שבא יעקב הרי חמשים ושלש, וכשפרש מאביו היה בן ששים ושלש הרי מאה ושש עשרה, והוא אומר שלשים ומאת שנה, הרי חסרים ארבע עשרה שנים הא למדת שאחר שקבל הברכות נטמן בבית עבר ארבע עשרה שנים. (אבל לא נענש עליהם בזכות התורה, שהרי לא פרש יוסף מאביו אלא עשרים ושתים שנה דהינו משבע עשרה עד שלשים ותשע כנגד עשרים ושתים שפרש יעקב מאביו ולא כבדו, והם עשרים שנים בבית לבן, ושתי שנים ששהה בדרך, כדכתיב (להלן לג יז) ויבן לו בית ולמקנהו עשה סכת, ופירשו רבותינו זכרונם לברכה מזה הפסוק ששהה שמונה עשר חדשים בדרך, דבית הוה בימות הגשמים וסכות הוו בימות החמה, ולחשבון הפסוקים שחשבנו לעיל משפרש מאביו עד שירד למצרים שהיה בן מאה שלשים שנים, שם אנו מוצאים עוד ארבע עשרה שנים, אלא ודאי נטמן בבית עבר בהליכתו לבית לבן ללמוד תורה ממנו, ובשביל זכות התורה לא נענש עליהם ולא פרש יוסף ממנו אלא עשרים ושתים שנה, מדה כנגד מדה) : **על נשיו.** הוסיף רשעה על, רשעתו שלא גרש את הראשונות:

@1 **ואלה תולדות יצחק בן אברהם** . על עשו ויעקב בניו האמורים למטה והזכיר הכתוב איך היתה ילידתם אברהם הוליד את יצחק לשון רש"י על ידי שכתוב יצחק בן אברהם הוזקק לומר אברהם הוליד את יצחק לפי שהיו ליצני הדור אומרים מאבימלך נתעברה שרה לכך צר הקב"ה קלסתר פניו דומה לאברהם שיאמרו הכל אברהם הוליד את יצחק ורבי אברהם אמר עוד שטעם הוליד גדל ורבה כמו יולדו על ברכי יוסף כמו שאמר וישלחם מעל יצחק בנו והנכון בעיני כי חזר עתה והחל באב היחס כמנהג הכתוב לחזור באנשי המעלה אל ראש היחס וכן בדברי הימים (א א יז יח) כתוב בני שם עילם ואשור וארפכשד ולוד וארם וארפכשד ילד את שלח וכאשר השלים חזר ואמר (שם כד) שם ארפכשד שלח עד אברם הוא אברהם וכן ביחוס בנימין חזר למפרע והחל ונר הוליד את קיש וקיש הוליד את שאול (שם ח לג ט לט) אף כאן אברהם הוליד את יצחק ויצחק הוליד את יעקב כאשר יזכיר וחזר לספר זה בעבור שאמר (לעיל כה יב) ואלה תולדות ישמעאל בן אברהם שאם אמר גם כן ואלה תולדות יצחק בן אברהם בלבד הנה השווה שניהם ביחוס ובמעלה ואף כי הקדים הבכור ועוד שהיה ראוי שיתחיל באברהם ויאמר "אלה תולדות אברהם" אבל לא רצה לעשות כן שלא ימנה ישמעאל ובני קטורה ולכך חזר והשלים אברהם הוליד את יצחק לומר כי הוא לבדו תולדותיו וכאלו לא הוליד אחר יחשב כמו שנאמר לו (לעיל כא יב) כי ביצחק יקרא לך זרע ולכך אמר למעלה (כה יב) גם כן אשר ילדה הגר המצרית שפחת שרה לאברהם לכבוד יצחק לומר שאין אלו תולדות היחס לאברהם רק הם בני האמה וכמו שאמר (לעיל כא יג) וגם את בן האמה לגוי אשימנו וכן עשה הכתוב אף בדברי הימים (א א כח) כי אמר מתחילה בני אברהם יצחק וישמעאל ואלה תולדותם בכור ישמעאל נביות והזכיר ובני קטורה פילגש אברהם ילדה את זמרן והיה ראוי שיאמר "בני יצחק" וחזר והחל ויולד אברהם את יצחק בני יצחק עשו וישראל
@4 **ותאמר אם כן למה זה אנכי** . אם כן גדול צער העבור למה זה אנכי מתפללת ומתאוה על ההריון לשון רש"י ואיננו נכון ורבי אברהם אמר כי שאלה את הנשים אם אירע להם ככה ותאמרנה לא ותאמר אם כן הדבר והמנהג למה זה אנכי בהריון משונה והנה הכתוב חסר ואיננו שלם בפירוש הזה והנכון בעיני כי אמרה אם כן יהיה לי למה זה אנכי בעולם הלואי אינני שאמות או שלא הייתי כטעם כאשר לא הייתי אהיה (איוב י יט)
@4 "ותלך לדרוש את ה'" - לשון רש"י להגיד מה יהא בסופה ולא מצאתי דרישה אצל ה' רק להתפלל כטעם דרשתי את ה' וענני (תהלים לד ה) דרשוני וחיו (עמוס ה ד) חי אני אם אדרש לכם (יחזקאל כ ג)
@5 **וטעם שני גוים בבטנך** . הודיע לה שלא תפחד כי בעבור שהיתה מעוברת תאומים הוא הריצוץ הזה בבטנה כי דרך נשים לה ויתכן שיאמר עוד כי בעבור היותם שני גוים שונאים ונלחמים זה בזה עשו בתחלת יצירתם מריבה רמז למה שיהיה ביניהם בסוף ועתה ינוחו ותמצא מנוח והשקט לנפשה
@10 **כי ציד בפיו** . אמרו המפרשים (הראב"ע והרד"ק) כי יתן ציד בפיו של יצחק או יביא ויחסר המעשה וכן למועד אשר שמואל (שמואל א יג ח) וה' אותי כגבור עריץ (ירמיהו כ יא) נתן או שם אותי ויתכן לפרש ויאהב יצחק את עשו בעבור כי בפיו של יצחק ציד תמיד כל היום יתאוה לאכול את הציד ותמיד הוא בפיו לא יאכל דבר אחר והוא המביא לו כאשר אמר איש יודע ציד והנכון בעיני כי היא מליצה כי עשו ציד בפי אביו יכנה האיש במעשה לתדירותו וכמוהו שבתך בתוך מרמה (ירמיהו ט ה) וכן ואני תפלה (תהלים קט ד) וכן אמרו בבראשית רבה (סג ו) קופרא טבא לפומיה כסא טבא לפומיה
@12 **מן האדום האדום הזה** . היה התבשיל מאודם מן העדשים שהיו אדומות או שרקחו בדברים אדומים ועשו לא ידע מה הוא וקרא שמו אדום על כן קרא שמו אדום כי לעגו עליו שמכר בכורה נכבדת בעבור תבשיל מעט כי סובא וזולל יורש (משלי כג כא)
@13 **מכרה כיום את בכורתך לי** . כיום דילהן כיום שהוא ברור כן מכור לי מכירה גמורה לשון רש"י ופשוטו כעת הזאת וכן ואתה עמוד כיום ואשמיעך את דבר אלהים (שמואל א ט כז) אותו כהיום תמצאון אותו (שם יג) קטר יקטירון כיום את החלב (שם ב טז) ולנו בשת הפנים כהיום הזה (דניאל ט ז) והנראה מדעת אונקלוס כי בעבור היות מכירת הבכורה לאחר מיתת אביהם אמר מכרה לי הבכורה לאיזה יום שתפול בו וזה שמוש "להן" בלשון ארמית להן את אזיל לאיזה מקום מן הן את מודע לי וכן בפרשת וישלח (ב"ר עח א) ולהן אינון אזלין מן הן דאתברון והוא לשון מורגל להם במקומות הרבה ובדניאל (ב יא) בפתחות הלמד כטעם אלהן להן אלהין די מדרהון עם בשרא לא איתוהי וכן להן מלכא מלכי ישפר עלך (שם ד כד) ואונקלוס תרגם זולתי "אלהין" אלא הן ובנוסחאות בדוקות ומדוקדקות מן התרגום כיום דלהי והוא כמו שפירשתי כי הי בלשונם איזה כמו שאומר בתלמוד (ב"ק צט) הי רבי מאיר הי רבי יהודה (ב"ב קמא) וזולתן ואפשר שעשה אונקלוס "כיום" כאלו הוא "ביום" מכרה ביום שתבא בו הבכורה כי כן מצאנו השמוש הזה לכ"ף כאשר ילכו אפרוש עליהם רשתי (הושע ז יב) משפטו באשר וכדמי בניך אשר נתתה להם (יחזקאל טז לו) כי כארבע רוחות השמים פרשתי אתכם (זכריה ב י) ויש אומרים (הרד"ק בשם אביו) כי אין מחיר הבכורה הנזיד רק הכתוב יספר כי בבקשו לאכול והוא עיף אמר לו יעקב מכור לי בכורתך בכסף ואחר כך אכול וענה לו בפחזותו על האכילה למה זה לי בכורה הרי היא מכורה לך ונשבע עליה וישבו לאכול ולשתות והכתוב לא פירש המחיר ואין זו דעתי
@15 **השבעה לי כיום** . כאשר אמר עשו למה זה לי בכורה אינני חפץ בה אמר לו יעקב השבעה לי כי לא תחפוץ בה ולא תירשנה לעולם ונשבע לו ואחר כן מכרה לו ונתן לו המחיר או הנזיד שבקש ויתכן שאמר עשו למה זה לי בכורה הנה היא מכורה לך ויאמר השבעה לי שלא תערער על המכירה לעולם ואמר הכתוב שנשבע לו ומכרה כאלו אמר מכרה ונשבע לו
@16 **ויבז עשו את הבכורה** . בז לדבר יחבל לו (משלי יג יג) אבל כבר אמר הטעם שבעבורו נאות למכירה מפני שהיה הולך למות בצודו החיות וקרוב הוא שימות בחיי אביו ואין לבכורה שום מעלה רק אחרי האב ומה תועיל לו הבכורה ואמר ויאכל וישת ויקם וילך ויבז כי אחר שאכל ושתה חזר השדה אל צידו וזו סיבת בזוי הבכורה כי אין חפץ בכסילים רק שיאכלו וישתו ויעשו חפצם בעתם ולא יחושו ליום מחר ורבי אברהם משתבש בכאן מאד שאמר כי בזה הבכורה בעבור שראה שאין ממון לאביו ורבים יתמהו כי עזב לו אברהם ממון רב וכאלו לא ראו בימיהם עשיר גדול בנעוריו בא לידי עוני בזקוניו והעד שהיה יצחק אוהב את עשו בעבור צידו ואלו היה לחם רב בבית אביו והוא נכבד בעיניו לא מכר את בכורתו בעבור נזיד ואם היה אביו בכל יום אוכל מטעמים מה טעם יאמר אליו הביאה לי ציד ולמה לא היו ליעקב בגדים חמודות ולא נתנה לו אמו כסף וזהב לדרך שאמר (להלן כח כ) ונתן לי לחם לאכול ובגד ללבוש למה לא שלחה לו הון והיא אוהבת אותו כי הוצרך לשמור הצאן והפסוק שאמר (להלן כו יג) ויגדל האיש קודם זקנתו ועורי לב יחשבו כי העושר מעלה גדולה לצדיקים והנה אליהו יוכיח ועוד ישאלו למה חסר השם ממון ליצחק אולי יודיעונו למה חסר מאור עיניו ואל ידחונו בקנה של דרש כי יש לו סוד ואין לנו לחפש כי עמקו מחשבות השם ואין כח באדם להבינם כל אלו דבריו ואני תמה מי עור עיני שכלו בזה כי הנה אברהם הניח לו הון רב ואבד העושר ההוא מיד קודם הענין הזה ומפני זה בזה את הבכורה כי הדבר הזה היה בנעוריהם קודם היות לעשו נשים כאשר יספר הכתוב ואחרי כן חזר והעשיר בארץ פלשתים עד כי גדל מאד ויקנאו בו שרי פלשתים ואחרי כן חזר לעניו והתאוה לציד בנו והמטעמים ואין אלו רק דברי שחוק ועוד כי הכתוב אמר (לעיל כה יא) ויהי אחרי מות אברהם ויברך אלהים את יצחק בנו והברכה תוספת בעושר ובנכסים וכבוד ואיה ברכתו שאבד הון אביו והעני ואחרי כן (להלן כו ג) ואהיה עמך ואברכך העשיר והעני אחרי כן ואם יש צדיקים שמגיע אליהם כמעשה הרשעים בענין העושר אין זה באותם שנתברכו מפי הקב"ה כי ברכת ה' היא תעשיר ולא יוסיף עצב עמה (משלי י כב) אבל היו האבות כלם כמלכים ומלכי גוים באים לפניהם וכורתים עמהם ברית וכתוב (להלן כו לא) וישבעו איש לאחיו ואם היה יצחק רע המזל מאבד נכסי אביו איכה אמרו ראו ראינו כי היה ה' עמך (שם כח) וכבר היה בעוכריו אבל בזוי הבכורה לעשו לאכזריות לבו ויתכן כי פי השנים בבכורה ממשפטי התורה לא היה כן לפנים רק לנחול מעלת האב ושררתו שיהיה לו כבוד ומעלה על צעירו ולכן היה אומר ליצחק אני בנך בכורך (להלן כז לב) לומר כי הוא הבכור הראוי להתברך וכן כי זה הבכור שים ימינך על ראשו (להלן מח יח) להקדימו בברכה ואולי היה נוטל גם בנחלה יותר מעט כי דין פי שנים מחדוש משפט התורה והציד אשר היה בפיו כן יעשו השרים והמלכים בוחרים בציד מכל מאכל וכל העמים יובילו מהם שי למורא והיה עשו מחניף את אביו להביא כל צידו אל פיו לאכול ממנו כרצונו תמיד ואהבת האב לבנו הבכור קלה להביא ומה שאמר לברך אותו אחר עשות לו המטעמים איננו שכר האכילה ושחד בהם אבל רצה ליהנות ממנו שתהיה נפשו קשורה בנפשו בעת ההנאה ויברך אותו בחפץ מלא ורצון שלם או שהיה יודע בנפשו כי אחר האכילה היתה מתענגת ושמחה ויחול עליה רוח הקודש כענין ועתה קחו לי מנגן והיה כנגן המנגן ותהי עליו יד ה' (מלכים ב ג טו) ולא נתנו ביד יעקב הון כי בורח היה ובלא ידיעת אחיו יצא מן הארץ לבדו ואלו נתנו לו הון ועבדים וגמלים היו מוסיפים בו קנאה לארוב לו ולהרגו ורבותינו אמרו (ב"ר סח ב) שגזלוהו ממנו ומי אמר לו שלא היו ליעקב בגדים חמודות שש ומשי ורקמה אבל הכתוב אמר כי עשו בלכתו השדה לצוד היה מחליפם בבגדי הציד ומפני שיצחק ממשש תמיד בבנו ובבגדיו הלבישה אותם את יעקב פן יכירנו בהם והלא אתה רואה שעשה כן וירח את ריח בגדיו (להלן כז כז) כי היה משים אותם בתוך נרד וכרכום כענין שכתוב (תהלים מה ט) מור ואהלות קציעות כל בגדותיך והיו הבשמים צומחים בארץ ישראל ועל כן אמר "כריח שדה" כי בעבור היותו איש שדה הריחו בגדיו מהם או ריח ציצי האילנות כמו שאמרו רבותינו (תענית כט) כריח השדה של תפוחים והשאלה על מאור עיניו שאלת עורי לב כי אם היתה סבה מאת השם הנה היא כדי שיברך את יעקב והוא ספור הכתוב (להלן כז א) ותכהין עיניו מראות ויקרא את עשו ועל דרך הפשט איננו רק ענין הזקנה וטעמו ויהי כי זקן יצחק ותכהינה עיניו בזקנתו קרא את עשו והנה ביעקב (להלן מח י) ועיני ישראל כבדו מזוקן לא יוכל לראות וכתוב באחיה השילוני (מלכים א יד ד) כי קמו עיניו משיבו ויספר במשה רבינו פלא (דברים לד ז) לא כהתה עינו
@17 **מלבד הרעב הראשון אשר היה בימי אברהם** . אולי לא היה רעב בעולם עד ימי אברהם (פרקי דר"א כו) ועל כן ימנה הכתוב ממנו כי מה צורך להזכיר זה והנכון בעיני כי זה להגיד כי היו זוכרים אותו הרעב הראשון ומספרים עליו שבעבורו ירד אברהם למצרים ושם עשה לו השם כבוד גדול ולכן היה יצחק חפץ ללכת בדרך אבותיו לירד שם עד שנאמר לו אל תרד מצרימה וטעם המניעה אמרו רבותינו (ב"ר סד ג) אתה עולה תמימה ואין חוצה לארץ כדי לך ולדעתי נכלל עוד בענין רמיזה בעתיד כי גלות אברהם אל מצרים מפני הרעב רמז שיגלו בניו שם ולכתו אל אבימלך לא היה גלות כי שם היה יושב ברצונו אבל ירידתו של יצחק שם מפני הרעב ירמוז לגלות כי גלה ממקומו בעל כרחו והלך אל ארץ אחרת והנה היה גלותו ממקומו אל ארץ פלשתים שהיא ארץ מגורי אביו וירמוז לגלות בבל שהוא מקום מגורי אבותם שהיו באור כשדים ודע כי הגלות הנזכר ירמוז למעשה יצחק כאשר לא לקחו אשתו ולא היה לו שם רק הגלות והפחד ומתחילה אמר הנוגע באיש הזה ובאשתו מות יומת ולימים חזר בו ואמר לך מעמנו ואחרי כן חזרו אליו בברית וכן גלות בבל גלו שם מפני זלעפות רעב ומעת היותם שם לא עבדום ולא ענו אותם אבל היו גדוליהם שרים במלכות ואחרי כן אמרו מי בכם מכל עמו יהי אלהיו עמו ויעל (עזרא א ג) והזהירו עליהם שרי עבר הנהר והפחות ואחרי כן בטלו הבנין והות בטלא עד זמן ועידן אחרי כן חזרו ונתנו רשות בבנין והזהירו ואמרו די להון מהקרבין ניחוחין לאלה שמיא ומצלין לחיי מלכא ובנוהי (שם ו י)
@17 "אל אבימלך מלך פלשתים" - לא נודע אם הוא אבימלך אשר היה בימי אברהם או שכל מלך פלשתים בעת ההיא יקרא כן כי גם בימי דוד יקרא אבימלך ודעת אונקלוס שהיה בנו וטעם וילך יצחק אל אבימלך כי היה בדעתו לרדת מצרימה והלך אל אבימלך בעל ברית אביו אולי ייטיב עמו בימי הבצורת ולא יצטרך לירד למצרים והנה אבימלך מפני בריתו של אברהם לא נגע בו ולא בביתו כלל אבל אנשי המקום המה בקשו ממנו דרך שאלה על אשתו והוא אמר אחותי היא ואף על פי כן לא נגע בה המלך ולא איש מאנשיו כי היו נזכרים בענין אברהם ולכך אמר כמעט שכב "אחד העם" יאמר אני לא נגעתי בה ונשמרתי ממנה אבל קרוב היה שיכשל בה אחד מאנשי הארץ והיית מביא עלינו אשם כאשר היה עלינו חטא בענין אביך
@18 **שכון בארץ אשר אומר אליך** . אין טעם שיאמר בבת אחת "שכון בארץ אשר אומר אליך גור בארץ הזאת" אבל פירושו אל תרד מצרימה ושכון כל ימיך בארץ שאומר אליך בכל פעם ופעם על פי ה' תסע ועל פי ה' תחנה וגור עתה בארץ הזאת בארץ פלשתים כי לך ולזרעך אתן אותה כדכתיב (יהושע יג ג) לכנעני תחשב חמשת סרני פלשתים ויתכן שיהיה "וירא אליו" מוקדם כי קודם צאתו ממקומו נאמר לו אל תרד מצרימה שכון בארץ אשר אומר אליך בהיותך שם וגור עתה בארץ הזאת בארץ כנען אשר תכלול עמים רבים וארצות רבות כי אני מצוך עתה שלא תצא ממנה לעולם כי כל הארצות האל אתן לזרעך והנה נסע ממקומו מפני הרעב ללכת בכל ארצות כנען לשכון בארץ אשר יאמר אליו ובבאו לגרר אמר לו כאן תשב ולא הוצרך לפרש כי ידוע הוא שלא עבר על מצות השם וכן על אחד ההרים אשר אומר אליך (לעיל כב ב) כאשר הזכרתי (שם פסוק ט)
@19 **והקמותי את השבועה** . אין צריך שיבטיח הקב"ה את יצחק שלא יעבור השבועה שנשבע לאביו כי לא אדם הוא להנחם (שמואל א טו כט) ואברהם אין לו זרע אחר בעל ברית לאלהים והשבועה איננה על תנאי כי ביעקב הוצרך מפני עשו אחיו לומר שבו יתקיים הברית ובזרעו (להלן לה יב) לא בעשו ונראה שזה המאמר "והקמותי את השבועה" יחשב שבועה ולכך תמיד יאמר בתורה (שמות לג א) הארץ אשר נשבעתי לאברהם ליצחק וליעקב אשר נשבעת להם בך (שם לב יג) כי לא מצאנו שבועה ליצחק בלתי זאת ורצה הקב"ה להשבע לכל אחד מן האבות להודיע שראוי כל אחד לכרות עמו ברית ושתהיה זכות כל אחד עומדת לפניו עם זרעם כי אף על פי שהראשונה תספיק תוספת זכות וכבוד הוא להם ולכן אמר (ויקרא כו מב) וזכרתי את בריתי יעקב ואף את בריתי יצחק ואף את בריתי אברהם אזכור והארץ אזכור כי כלם בעלי ברית לאלהים ויתכן שהוסיף לו ליצחק בשבועה הזאת שיקיים בו בעצמו השבועה אשר נשבע לאברהם אביו שיהיה הוא ברכה בעמים כאשר אמר לאברהם אביו והתברכו בזרעך כל גויי הארץ ויהיה פירוש הכתוב והקמותי בך את השבועה אשר נשבעתי לאברהם אביך כי אתה ברכה בעמים וכן אמר עוד ביעקב (להלן כח יד) ונברכו בך כל משפחות האדמה ובזרעך
@21 **וישמור משמרתי** . לשון רש"י בקולי כשנסיתי אותו משמרתי גזירות להרחקה כגון שניות לעריות שבות לשבת מצותי מצות שאלו לא נכתבו דין הוא שיכתבו כגון גזל ושפיכות דמים חקותי דברים שיצר הרע ועו"ג משיבין עליהם כגון אכילת חזיר ולבישת שעטנז שאין טעם בדבר אלא המלך גזר חקו על עבדיו ותורתי להביא תורה שבעל פה הלכה למשה מסיני ואם כן יהיה כל זה בנוי על דעת שהיה אברהם מקיים ומשמר את התורה עד שלא נתנה וכך אמרו (ב"ר צד ג) בפסוק ויתן להם יוסף עגלות (להלן מה כא) שפירש ממנו בפרשת עגלה ערופה שהיה עוסק בתורה כשם שהיו אבותיו ועד עכשו לא נתנה תורה והרי כתוב וישמור משמרתי מצותי חקותי ותורותי ושם אמרו שהיה משמר אפילו דקדוקי תורה והיה מלמד לבניו וכו' ויש לשאול אם כן איך הקים יעקב מצבה (להלן כח יח) ונשא שתי אחיות וכדעת רבותינו (ב"ר עד יא) ארבע ועמרם נשא דודתו (שמות ו כ) ומשה רבינו הקים שתים עשרה מצבה (שם כד ד) והאיך אפשר שיהיו נוהגים היתר בתורה במה שאסר אברהם אביהם על עצמו וקבע לו השם שכר על הדבר והוא יצוה את בניו ואת ביתו אחריו ללכת בדרכיו וביעקב דרשו (ב"ר עט ו) ששמר את השבת וקבע תחומין ואפשר שיהיה זה בשבת מפני שהיא שקולה ככל התורה כולה (ירושלמי ברכות פ"א ה"ה) שהיא מעידה על מעשה בראשית ואולי נאמר משמרתי שניות לעריות של בני נח ומצותי גזל ושפיכות דמים חקותי אבר מן החי וכלאים של הרבעת בהמה והרכבת אילן ותורותי דינין ואסורי עבודה זרה שאלו כולן נצטוו בהן בני נח והוא השומר והעושה רצון בוראו ומשמר אפילו דקדוקין וחומרות במצות שלהן וכמו שהזכירו ע"ז של אברהם אבינו ארבע מאה פרקי הוות (ע"ז יד) ודרשו ב"מאה שערים" שמדדוה למעשרות (ב"ר סד ו) כי היו האבות נדיבי עמים לתת מעשרות לעניים או לכהני ה' כגון שם ועבר ותלמידיהם כענין והוא כהן לאל עליון (לעיל יד יח) והנראה אלי מדעת רבותינו שלמד אברהם אבינו התורה כלה ברוח הקדש ועסק בה ובטעמי מצותיה וסודותיה ושמר אותה כולה כמי שאינו מצווה ועושה ושמירתו אותה היה בארץ בלבד ויעקב בחוצה לארץ נשא האחיות וכן עמרם כי המצות משפט אלהי הארץ הן אף על פי שהוזהרנו בחובת הגוף בכל מקום (קדושין לו) וכבר רמזו רבותינו הסוד הזה (בספרי דברים פסקא מג) ואני אעירך בו בעזרת השם (ויקרא יח כה דברים יא יח) והמצבה מצוה שנתחדשה בזמן ידוע היא כמו שדרשו (בספרי) באשר שנא ה' אלהיך (דברים טז כב) ששנאה אחר היותה אהובה בימי האבות וביוסף דרשו (ב"ר צב ד) שהיה משמר את השבת אפילו במצרים מפני שהיא שקולה כנגד כל המצות לפי שהיא עדות על חדוש העולם והיה עושה כן ללמד את בניו אמונת בריאת העולם להוציא מלבם כונת עבודה זרה ודעות המצרים וזאת כונתם ועל דרך הפשט נאמר שיהא משמרתי אמונת האלהות שהאמין בשם המיוחד ושמר משמרת זו בלבו וחלק בה על עובדי העבודה זרה וקרא בשם ה' להשיב רבים לעבודתו מצותי ככל אשר צוהו בלך לך מארצך ועולת בנו וגרישת האמה ואת בנה חקותי ללכת בדרכי השם להיות חנון ורחום ועושה צדקה ומשפט ולצות את בניו ואת ביתו בהם ותורותי המילה בעצמו ובניו ועבדיו ומצות בני נח כלן שהן תורה להם
@23 **ויאמר אחותי היא** . ועל הבנים לא שאלוהו כי יאמר בני אשה אחרת הם לו
@30 **ויהי לו מקנה צאן ומקנה בקר ועבודה רבה** . אתונות וגמלים וחמורים ועבדים ושפחות ויזכיר הכתוב זה ולא יזכיר כסף וזהב כאשר נאמר באברהם (לעיל יג ב) בעבור כי גדולתו אשר נתגדל בה בארץ פלשתים במקנה ובעבודה היתה ויקנאו אותו פלשתים בענין ההוא וזה טעם כי עצמת ממנו מאד אמר לו גם לי שאני המלך אין בביתי מקנה ועבודה כמוך וחרפה היא לנו להיות ביתך גדול מבית המלך
@33 **בנחל גרר** . רחוק מן העיר וישב ויחפור את בארות המים אשר חפרו בימי אברהם אביו ופלשתים סתמום קודם שנסע יצחק מגרר חזר וחפרן לשון רש"י ונראה מדבריו שהם הבארות הנזכרים כאן כמו שאמר (בפסוק טו) סתמום פלשתים וימלאום עפר וזה איננו כן כי היאך יתנו לו הם רשות והם אמרו "תקלה הם לנו מפני הגייסות" אבל הם אחרים במקום אחר כי נחל גרר שם מקום או שהנחל נמשך מגרר אל ארץ אחרת וכאשר קנאו בו פלשתים הם השרים אשר בגרר מדינת המלך סתמו הבארות אשר לו מירושת אביו בגבול עיר גרר והמלך שלחו מעיר מושב כסאו והלך לו לעיר אחרת ואולי איננה ממלכותו אף על פי שהיא בארץ פלשתים ושם בארות אחרים שחפר אברהם שגר במקום ההוא ימים רבים ופלשתים יושבי הארץ כאשר מת אברהם ויצחק לא ישב שם סתמום ולא לשנאתו רק בימי אברהם לא רצו לסתמם מפני כבודו כי אמרו אולי ישוב לשבת בארץ ולכן שב יצחק ויחפור אותם בנחל ורועי נחל גרר רבו עמו לאמר לנו המים והטעם "לאמר" הנה הבאר בנחל ומימי הנחל הם אשר ימצו שם ומתמציתם ימלא הבור והנחל יתמעט בהם והנה הם שלנו ועל כן הזכיר הכתוב וימצאו שם באר "מים חיים" לאמר כי היה מקור נובע מים חיים אין מימיו מן הנחל כאשר אמרו מריביו
@36 **ויקרא שם הבאר עשק** . יספר הכתוב ויאריך בענין הבארות ואין בפשוטי הספור תועלת ולא כבוד גדול ליצחק והוא ואביו עשו אותם בשוה אבל יש בדבר ענין נסתר בתוכו כי בא להודיע דבר עתיד כי "באר מים חיים" ירמוז לבית אלהים אשר יעשו בניו של יצחק ולכן הזכיר באר מים חיים כמו שאמר (ירמיהו יז יג) מקור מים חיים את ה' וקרא הראשון עשק ירמוז לבית הראשון אשר התעשקו עמנו ועשו אותנו כמה מחלוקות וכמה מלחמות עד שהחריבוהו והשני קרא שמה שטנה שם קשה מן הראשון והוא הבית השני שקרא אותו כשמו שכתוב בו (עזרא ד ו) ובמלכות אחשורוש בתחילת מלכותו כתבו שטנה על יושבי יהודה וירושלם וכל ימיו היו לנו לשטנה עד שהחריבוהו וגלו ממנו גלות רעה והשלישי קרא רחובות הוא הבית העתיד שיבנה במהרה בימינו והוא יעשה בלא ריב ומצה והאל ירחיב את גבולנו כמו שנאמר (דברים יט ח) ואם ירחיב ה' אלהיך את גבולך כאשר דבר וגו' שהוא לעתיד וכתיב בבית השלישי (יחזקאל מא ז) ורחבה ונסבה למעלה למעלה ופרינו בארץ שכל העמים יעבדוהו שכם אחד
@40 **אל תירא כי אתך אנכי** . בעבור שהבריחו אבימלך מעליו מקנאתם בו וגם רועי גרר רבו עמו היה מתירא פן יאספו עליו ויכוהו הוא וביתו והבטיחו הקב"ה שלא יירא מהם ויברך אותו ואז נתן בלבם שהלך לפניו המלך בכבוד גדול יותר מאשר עשה לאביו כי בא עם פיכול שר צבאו ועוד הוסיף להביא עמו רבים רעיו
@45 **אם תעשה עמנו רעה כאשר לא נגענוך** . יאמר אם תעשה עמנו רעה כמו שאנחנו לא נגענוך אתה עתה ברוך ה' ואין לאל ידינו לעשות עמך רע אבל ישתנה העת בעבור החמס שאתה עושה ותצטרך לשוב אל ארצנו ונשיב לך גמול וטעם לא נגענוך שלא נפתה לבנו על אשתך ליגע באחד מכם כלשון הנוגע באיש הזה ובאשתו ועשינו עמך רק טוב לשמור את כל אשר לך בצוותינו את העם להשמר מכם ונשלחך בשלום כי גם בקנאתנו בך לא לקחנו מכל העושר אשר עשית עמנו ונשלחך עם כל אשר לך בשלום וענין היראה הזאת אשר פחדו ממנו אינו נראה שירא מלך פלשתים שלא יבא עליו יצחק למלחמה אבל הבטיחם אברהם לו ולנינו ולנכדו (לעיל כא כג) ועתה אמרו בלבם בעבור שהפרנו אנחנו את בריתנו עם יצחק ושלחנוהו מעלינו גם הוא יפר את בריתו עמנו ויגרש זרעו את זרעינו מן הארץ ולכן עשו עמו ברית חדשה והתנצלו לאמר לו שלא הפרו הברית הראשונה שלא עשו עמו רק טוב וזה טעם תהי נא אלה בינותינו שנבא עתה עמך באלה להחרים על כל מי שיעבור על הברית כטעם לעברך בברית ה' אלהיך ובאלתו (דברים כט יא) ויתכן שהיה אברהם גדול מאד ורב כח שהיו בביתו שלש מאות איש שולף חרב ולו בעלי ברית רבים והוא גם בן חיל אשר לבו כלב האריה ורדף ארבעה מלכים גבורים מאד ונצחם וכאשר ראו הצלחתו כי היא מאת האלהים פחד ממנו מלך פלשתים פן יכבוש ממנו מלכותו ונקל זאת ממלחמת ארבעת המלכים אולי שמע עוד דבר השם שנתן לו הארץ ולכן בא עמו בברית והשביעו אם תשקור לי ולנכדי כי היה שקר אם ימרוד על המלך וחשב כי אפשר שיחיה אברהם עד מלוך נכדו וכמעשה אבות עשו בנים כי היה יצחק גדול כאביו ופחד המלך פן ילחם בו בגרשו אותו מארצו
@48 **ויבואו עבדי יצחק ויגידו לו על אודות הבאר אשר חפרו** . הוא האמור בו למעלה (בפסוק כה) ויכרו שם עבדי יצחק באר כי החלו לחפור אותו ובא אבימלך אליו בימים ההם וביום הברית בלכתם ממנו בשרוהו כי מצאו מים וקרוב לי שהוא הבאר שכרה אברהם ונתן לו שבע כבשות לעדה (לעיל כא ל) כי סתמוהו פלשתים עם האחרים וישב יצחק ויחפור אותו ויקרא לו גם הוא שם כשם אשר קרא לו אביו ועל כן שם העיר באר שבע על שם הבאר אשר קראוהו כן האב והבן כי שם נשבעו שניהם והבאר הזאת להם תרמז על משכן שילה ופלשתים סתמוהו בהלקח הארון (שמואל א ד יא) וחזר וחפרו בו כי כן השיבו הארון עם הדורון לאלהים (שם ו יא)
@55 **בעבור תברכך נפשי** . היה בדעתו לברך אותו שיזכה הוא בברכת אברהם לנחול את הארץ ולהיות הוא בעל הברית לאלהים כי הוא הבכור ונראה שלא הגידה לו רבקה מעולם הנבואה אשר אמר ה' לה ורב יעבוד צעיר כי איך היה יצחק עובר את פי ה' והיא לא תצלח והנה מתחלה לא הגידה לו דרך מוסר וצניעות כי ותלך לדרוש את ה' שהלכה בלא רשות יצחק או שאמרה "אין אנכי צריכה להגיד נבואה לנביא כי הוא גדול מן המגיד לי" ועתה לא רצתה לאמר לו "כך הוגד לי מאת ה' טרם לדתי" כי אמרה באהבתו אותו לא יברך יעקב ויניח הכל בידי שמים והיא ידעה כי בסבת זה יתברך יעקב מפיו בלב שלם ונפש חפצה או הם סבות מאת ה' כדי שיתברך יעקב וגם עשו בברכת החרב ולו לבדו נתכנו עלילות
@58 **ואברככה לפני ה' לפני מותי** . לא נזכר בכל הפרשה לפני ה' רק במקום הזה כי אמרה לו אמו הברכה לפני ה' תהיה ברוח הקדש ואם יתברך בה עשו אחיך תתקיים בו בזרעו לעולם ואין לך עמידה לפניו
@63 **אולי ימשני אבי** . אין הטעם שימושהו להכיר אותו אבל אמר אולי יקרב אותי אל עצמו לנשק לי או לשום ידו על פני כדרך חבת האב על בנו וימצא במשוש שאני חלק ואני תמה איך לא פחד מהיכר הקול וכל בני אדם נכרים בקולם כמו שאמרו רבותינו (גיטין כג) היאך סומא מותר באשתו והיאך בני אדם מותרין בנשותיהן בלילה אלא בטביעות עינא דקלא ואם סתם בני אדם מכירין כן מה יהיה ביצחק החכם והבקי להכיר בין בניו שתהיה לו באמת טביעות בקול אולי היו האחים האלה דומים בקולם ולכך אמרו (ב"ר סה יט) כי הקול קול יעקב דבריו שמדבר בלשון רכה ומזכיר שם שמים או שהיה משנה קולו לדבר כלשון אחיו כי יש בבני אדם יודעים לעשות כן
@66 **עשו בנה הגדול ויעקב בנה הקטן** . להפליג בענין הצדקת כי המנהג במולידים להכיר את הבכור בברכה ובכבוד ובמתן והיא מדעתה צדקת הקטן ורשעת הגדול תשתדל בכל הטורח הזה להעביר הברכה והכבוד מן הגדול אל הקטן וכן יאמר למטה (פסוק מב) ויגד לרבקה את דברי עשו בנה הגדול ותשלח ותקרא ליעקב בנה הקטן
@72 **גשה נא ואמשך בני** . לשון רש"י אמר בלבו אין דרך עשו להיות שם שמים שגור בפיו וכן בבראשית רבה ואני תמה כי לא היה עשו רשע בעיני אביו ואולי היה חושב בלבו כי בעבור היותו איש שדה ולבו על הציד איננו מזכיר שם שמים מפחדו שלא יזכירנו במקום שאינו טהור ומבלי כוונה ונחשב לו זה בעיני אביו ליראת שמים ועל דרך הפשט יהיה זה בעבור טביעות הקול
@79 **מטל השמים** . אין הברכה שיתן לו האלהים מטל השמים כי הטל ירד בכל מקום ואלו אמר שיתן רבוי טל או שירד בעתו כענין ונתתי גשמיכם בעתם (ויקרא כו ד) היתה ברכה אבל פירושו כי הזכיר בו ברכת ה' כריח שדה אשר ברכו ה' והטעם אשר ברכו ה' לבני כי השם ברך אותו בשדה לומר שיצליחנו שם בצידו ולא ימות ולא תבואהו בו רעה ואמר
@79 "ויתן לך האלהים מטל השמים ומשמני הארץ" - והברכה תוספת ורבוי או שיהיה ורב דגן ותירש בתוספת הוא"ו ושיעורו ויתן לך האלהים מטל השמים ומשמני הארץ רב דגן ותירוש והנכון בעיני כי מתת האלהים תמיד הוא ואין לו הפסק לעולם ולכן אמר ויתן לך האלהים כל ימיך על אדמתך מטל השמים ויתן לך משמני הארץ כלומר השמנה בכל הארצות כענין שכתוב (יחזקאל כ ו) צבי היא לכל הארצות ורבי אברהם אמר כי מ"ם מטל מושך עצמו ואחר עמו וממשמני הארץ ולעשו לא נתנו במתת אלהים ולא ברבוי אבל אמר גם לך אצלתי אחריו ומשמני הארץ ומטל השמים יהיה מושביך בעוד אשר תשב שם ירמוז כי יכלה ויאבד אך בעודו יהיה חלקו טוב
@80 **ארריך ארור ומברכיך ברוך** . ובבלעם הוא אומר (במדבר כד ט) מברכיך ברוך ואורריך ארור הצדיקים תחלתן יסורין וסופן שלוה ואורריהן קודמין למברכיהן והרשעים תחלתן שלוה וסופן יסורין לפיכך הקדים בלעם ברכה לקללה לשון רש"י מבראשית רבה (סו ד) ואם כן למה אמר הקב"ה לאברהם (לעיל יב ג) ואברכה מברכיך ומקללך אאור וזה איננו קשה כי חזר שם ונברכו בך והנה הברכה בראש ובסוף או בעבור מה שפירשנו שם דבר בלשון יחיד ורבים כי הכל יברכוהו והיחיד אשר יקלל אותו יואר
@83 **מי אתה** . כאשר אמר לו "יקום אבי" היה חושב שהוא יעקב וידע שאכל מציד עשו וברך אותו ועשה גם הוא מטעמים שיברך גם אותו ולכן שאלו מי אתה לדעת האמת
@84 **בטרם תבא ואברכהו גם ברוך יהיה** . אין דרך החרד חרדה גדולה עד מאד וצועק "מי הוא אשר רמני לברך אותו" שישלים צעקתו לאמר מיד "גם ברוך יהיה" אבל היה ראוי שיקללהו ועוד כי היה עשו צועק עליו לאמר "ולמה תברכהו עתה אבי" ואיך יאמין עשו כי במרמה היה מתחלה בראותו כי עתה יברך אותו ברצונו והנכון בעיני שהוא לשון הווה יאמר מי איפוא הוא הצד ציד אשר היה יכול לרמותי שאברכהו וגם שיהיה ברוך על כל פנים כי ידעתי כי ברוך הוא או טעמו וגם ברוך יהיה על כרחי שאי אפשר לי להעביר הברכה ממנו כי מאז שברך אותו ידע ברוח הקדש שחלה ברכתו עליו וזהו טעם החרדה הגדולה אשר חרד כי ידע שאבד בנו האהוב לו ברכתו לעולם וזה טעם בא אחיך במרמה כי אחר שאמר מי איפוא נתן דעתו שהבא אליו היה יעקב שאי אפשר שתחול הברכה רק בזרעו
@88 **ואת כל אחיו נתתי לו לעבדים** . איננו ברכת "הוה גביר לאחיך" שכבר אמר הן גביר שמתיו לך אבל יתכן שיהיה הוא הגביר ולא יהיו הם עבדים כענין כי יהודה גבר באחיו (דהי"א ה ב) אבל אמר "נתתי לו לעבדים" ממאמרו וישתחוו לך בני אמך כי הוא השתחואת העבד לאדוניו כמו שאמר "יעבדוך עמים" ויכפול וישתחוו לך לאומים וטעם ואת כל אחיו כטעם "אחיך" ו"בני אמך" יזכירם בלשון רבים לרמוז על כל זרעו של עשו ורבי אברהם אמר בני הפילגשים
@90 **הנה משמני הארץ יהיה מושבך** . טעם "הנה" לאמר הנה אוכל לתת לך משמני הארץ ומטל השמים כי לשניכם יספיק שיהיה משמני הארץ וטל השמים אבל בענין הממשלה שלו תהיה ולו תעבוד ולא נתן לו גם כן רב דגן ותירוש כאחיו כי רצה לכבד המבורך ראשונה עליו ואחרי כן אמר ליעקב ויתן לך את ברכת אברהם לרשתך את ארץ מגוריך (להלן כח ד) להיות לו רב הדגן והתירוש בארץ כנען מתנת אברהם ולעשו יהיה הטל ומשמני הארץ בארץ אחרת
@91 **וטעם ועל חרבך תחיה** . כמו בחרבך וכן כי לא על הלחם לבדו יחיה האדם (דברים ח ג) בלחם ואין הברכה שתהיה מחיתו משלל האויבים בחרבו כי הנה נתן לו משמני הארץ ומטל השמים ובה יחיה אבל הענין לומר שיחיה במלחמותיו כי ינצח ולא יפול בחרב אויב ועל כן אמר ואת אחיך תעבוד שלא תתגבר עליו והוא יגבר עליך והיה כאשר תריד בשיחך מתגרת ידו ופרקת עלו מעל צוארך ירמוז לישראל שלא יתגרו בם יותר מדאי לעשות עמם רעה והוא מה שצוה הכתוב (דברים ב ד-ה) ונשמרתם מאד אל תתגרו בם וגו' וכך הזכירו רבותינו (ירושלמי ר"ה א א) אמרו כי ששת חדשים ישב שם יואב וכל ישראל עד הכרית כל זכר באדום (מלכים א יא טז) אמר לו הקב"ה אני אמרתי אל תתגרו בם ואתה התגרית בהם חייך שאין ששה חדשים הללו נמנין לך ולמלכותך מדכתיב (שם ב יא) והימים אשר מלך דוד על ישראל ארבעים שנה והוא מלך ששה חדשים יותר דכתיב ( ה ה) בחברון מלך על (ישראל) יהודה שבע שנים וששה חדשים ועוד אמרו (דב"ר א טז) אמר לו הקב"ה דוד ידיך חדודות וחרוצות ואני מבקש לרדות בהם את עולמי וכו'
@92 **ויאמר עשו בלבו** . אמר רבי אברהם יתכן שגלה סודו לאחד מאוהביו ואין צורך כי ההסכמה בדבר אשר ימלך אדם עם לבו תקרא אמירה עם הלב אף על פי שיהיה בה דבור בשפתים וכן בלב ולב ידברו (תהלים יב ג) כי הרצון יקרא "לב" וכל ישראל לב אחד להמליך את דוד (דהי"א יב לח) שהיו כלם על אותה ההסכמה והיו מדברים בה וכן ויאמר ירבעם בלבו (מלכים א יב כו) וכן אמר אליעזר (לעיל כד מה) אני טרם אכלה לדבר אל לבי והיתה שם תפלה בשפתיו ויאמר ה' אלהי אדני אברהם (שם יב) אבל טרם אכלה לדבר אל לבי טרם השלימי מה שעלה בדעתי
@92 "ויאמר" - כאן כי כאשר באה משטמה גדולה בנפש עשו לשטום את יעקב על הברכה עלה בלבו שיהרוג את אחיו והיה מתנחם בזה מרוע לבו וזה טעם ויגד לרבקה את דברי עשו ולכך אמרה מתנחם לך ורש"י כתב ברוח הקודש הוגד לה מה עשו מהרהר בלבו וכן בבראשית רבה (סז ט) ואם כן יהיה "דברי עשו" מחשבתו עם הלב כמו דברתי אני עם לבי (קהלת א טז) והנה עשו היה אומר יקרבו ימי אבל אבי כי בחייו לא יצערנו או מפחדו שלא יקללנו ותהפך ברכתו לקללה ורבקה פחדה שמא ימות הזקן פתאום ויהרגנו או שמא יזדמן לו בחייו ויהרגנו
@93 **וטעם ותשלח ותקרא ליעקב** . כי היה יעקב במקום אחר איננו באהל אביו ואמו כי היה מתחבא מפני עשו אחיו שהיה צועק עליו והיה מתבייש ממנו או מתפחד
@93 "מתנחם לך להרגך" - מתנחם הוא על הברכות בהריגתך לשון רש"י ופשוטו מתנחם בך וכן כי בוחר אתה לבן ישי (שמואל א כ ל) והחזיק לו (שם ב טו ה) ורבים כן או פירושו מתנחם עליך כמו כי כן צוה לו המלך (אסתר ג ב) אבל אונקלוס אמר כמין לך אורב לך ונראה מדעתו כי טעם מתנחם לך שמראה עצמו לך מנוחם על ענין הברכות וכאלו אינו מקפיד בהן והוא מארב כדי שלא תשתמר ממנו ותרגם הענין לא הלשון
@102 **אחי רבקה אם יעקב ועשו** . בעבור שאמר שצוה יצחק את יעקב לקחת לו אשה מבנות לבן אחי אמו הזכיר הכתוב שהיה גם כן אחי אמו של עשו וראוי היה שיצוה גם כן לעשו אבל מדעתו שברכת אברהם תהיה ליעקב ולזרעו עשה כן והזכיר כי עשו שמע שצוה אותו שלא יקח אשה מבנות כנען ושילך אל לבן אחי אמו והוא שמע לעשות רצון אביו שלא לקחת אשה מבנות כנען אך לא עשה כראוי שיקח מבנות לבן אף על פי שהוא אחי אמו ועוד הזכיר שלקח אותה על נשיו ולא גרש את הרעות כי הלך על תאות נפשו יותר מרצון אביו חסלת פרשת תולדות
